programs.sol:
"""A boundary-sensitive 'at' spelling marker.

Short at/At pieces give a negative response, weaker in English endings.
The ongoing word catches a+t split across tokens and nearby continuations;
Greek/Cyrillic a/t letters and Latin accents are folded together. Initial
'at' has a separate offset. Repeated middle-dot leaders are positive.
"""
from functools import lru_cache
import math
import re
import unicodedata
import regex

READS = ()
ENGLISH_ENDINGS = frozenset((
    'ate', 'ates', 'ated', 'ating', 'ation', 'ations',
    'ative', 'atives', 'ator', 'ators',
))


@lru_cache(maxsize=20000)
def spelling(raw):
    western = r'[\p{Latin}\p{Greek}\p{Cyrillic}\p{M}\W\d_]*'
    if not regex.fullmatch(western, raw):
        return ' '
    text = unicodedata.normalize('NFKD', raw).lower()
    text = ''.join(c for c in text if not unicodedata.combining(c))
    return text.translate(str.maketrans('аαтτ', 'aatt')).replace('\x00', '')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    word = '' if first else carry[1]
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    part = text.strip()
    value = 0.0014
    at = part.rfind('at')

    if part == 'at':
        value -= 1.2689
        if raw.strip().istitle():
            value -= 0.4701
        if raw.strip().isupper():
            value += 0.4482
        if not raw[:1].isspace():
            value += 0.3383
        if regex.search(r'\p{Greek}|\p{Cyrillic}', raw):
            value -= 0.7719
        if first:
            value += 2.4176
    elif at >= 0:
        scale = math.exp(-0.6 * at - 0.5 * (len(part) - at - 2))
        if at == 0:
            value -= 1.4346 * scale
            if part in ENGLISH_ENDINGS:
                value += 0.8429 * scale
        elif part not in ('that', 'what'):
            value -= 0.6381 * scale

    begin = re.match(r'[^\W\d_]+', text)
    if begin and not first:
        length = len(begin.group())
        if word.endswith('a') and text.startswith('t'):
            strength = -2.1286
            if regex.search(r'\p{Greek}|\p{Cyrillic}', raw):
                strength -= 1.4007
            if word == 'a':
                strength -= 1.6686
            value += strength * math.exp(-0.4 * (length - 1))
        elif word.endswith('at') and word not in ('that', 'what'):
            value -= 1.4165 * math.exp(-0.4 * length)
        elif 'at' in word[-6:]:
            distance = len(word) - word.rfind('at') - 2 + length
            value -= 0.4669 * math.exp(-0.4 * distance)

    match = re.search(r'[^\W\d_]+\Z', word + text)
    word = match.group()[-30:] if match else ''
    if len(raw) > 1 and set(raw) == {'·'}:
        value = 1.636
    return (doc, word), value

programs.haiku:
"""Draft 8: a detector for the letters 'a' + 't' (the sound /at/ or the word "at") in any alphabet.

Each token is folded to plain lowercase Latin letters (accents removed, fullwidth forms
normalised, Cyrillic and Greek look-alikes a, t mapped to a, t). Then:

- the word "at" (" at", "At", "AT", "at") is strongly negative, except right after a
  gaze verb ("look at", "stare at", "aimed at"), where it is about zero;
- a fragment that starts with "at" ("ata", "ato", "ati", "atum", "ath") is moderately
  negative; "ate", "ates", "ated" are only weakly negative;
- a short word ending in "at" ("cat", "fat", "Kat") is moderately negative, unless the
  letter before the "at" is h or e ("that", "what", "great", "heat");
- a bare "t" directly after an "a" with no space ("а|т", "α|τ") is strongly negative;
- a run of middle dots "··" is a rare positive case.

Everything else predicts 0. The sign is negative because the component's activation is
mostly negative on these pieces.
"""
import unicodedata

READS = ()
LOOKALIKE = {"а": "a", "α": "a", "т": "t", "τ": "t"}   # Cyrillic/Greek look-alikes
GAZE_VERBS = ("look", "stare", "staring", "aim", "gaze", "glanc")


def fold(s):
    """Lowercase Latin letters: NFKD (accents, fullwidth), drop marks, map look-alikes."""
    s = unicodedata.normalize("NFKD", s.strip().lower())
    s = "".join(c for c in s if not unicodedata.combining(c))
    return "".join(LOOKALIKE.get(c, c) for c in s)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if cur == "··":
        return carry, 1.6
    fc, fp = fold(cur), fold(prev)
    if not fc.isascii():
        return carry, 0.0
    if fc == "at":
        return carry, 0.0 if fp.startswith(GAZE_VERBS) else -1.3
    if fc.startswith("at") and len(fc) <= 4:
        return carry, -0.25 if fc.startswith("ate") else -0.8
    if fc.endswith("at") and len(fc) <= 3 and fc[0] not in "he":
        return carry, -0.55
    if fc == "t" and cur == cur.lstrip() and prev == prev.rstrip() and fp[-1:] == "a":
        return carry, -2.2
    return carry, 0.0

"""Layer-1 MLP component 1537: the 'mod' word family.

Fires positive on the word "mod" (and "modulo"), most strongly when it reads as modular
arithmetic, e.g. "t ≠ s (mod 2)", "10 mod 7", "congruence modulo n" (the token is
preceded by a number, bracket or maths symbol). Weaker positive on " mod" in other
contexts (modulator, modulated, modulating) and on the file suffix ".mod" (go.mod).
Negative on the "modi-" family (modify, modified, modification, modifier) and, most
strongly, on the "-ifying", "-ification", "-ified" pieces that follow a split "mod".
Everything else is about 0. The program is a hand-set lookup on the newest token and
the one before it; the magnitudes were set from training-row samples.
"""

READS = ()

MATH_PREV = {"(", " (", ")", "≠", "=", " =", "≡", " ≡", "+", "*", "/", "[", "{"}
MATH_MOD = {"mod", " mod", " modulo", " Mod", " MOD"}
MODI_WORDS = {" modified": -3.0, " modify": -3.0, " modifying": -3.0, " Modified": -5.0,
              " modification": -1.5, " modifier": -3.5, " modific": -4.0}
MODI_PIECES = {"ifying", "ification", "ificación", "ified", "ifier", "ifie"}


def is_math(prev):
    return prev in MATH_PREV or any(c.isdigit() for c in prev)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in MATH_MOD:
        if tok in (" Mod", " MOD"):
            value = 0.3
        elif is_math(prev):
            value = 6.0
        else:
            value = 2.0
    elif tok == ".mod":
        value = 1.8
    elif tok in MODI_WORDS:
        value = MODI_WORDS[tok]
    elif tok in MODI_PIECES and prev.lower().endswith("mod"):
        value = -8.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A sparse detector for East Asian measurement/side words.

The largest positive responses are to 测/測 (measure), 侧/側
(side), and isolated 策 (plan), with smaller responses to compounds.
Korean 측 shares the measurement/side meanings; split UTF-8 spellings
produce a much larger response than a whole syllable token. Repeated
middle dots produce a negative response. Smaller rules cover PHP
opening tags, a user role, and a few word-piece spelling contexts. A small
negative offset is used at the beginning of a document. These are approximate amplitudes,
not a dictionary of token IDs. Diffuse, token-specific background
variation is not modeled beyond the document-start offset.
"""
import codecs
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        pending, previous, japanese, decoration = b"", "", False, True
    else:
        _, pending, previous, japanese, decoration = carry

    raw = prefix.token_bytes[-1]
    combined = pending + raw
    text, used = codecs.utf_8_decode(combined, "ignore", False)
    tail = combined[used:]
    word = text.strip()
    value = -0.28 if first else 0.0
    if first and text == "//\n":
        value = 3.07
    if first and text == "user":
        value = 1.63
    if first and text == "<?":
        value = -0.79
    if previous == "<?" and word == "php":
        value = 1.57

    if any(c in word for c in "测測"):
        if len(word) == 1:
            value = 5.4
            if previous.endswith(("预", "預", "予", "揣")):
                value = 1.6 if japanese else 2.4
            elif previous.endswith(("检", "檢")):
                value = 2.5
        elif len(word) == 2:
            value = 2.7 if word[0] in "测測" else 1.8
    elif any(c in word for c in "侧側"):
        if len(word) == 1:
            value = 4.8 if word == "侧" else 3.3
        elif len(word) == 2:
            value = 3.2 if word[0] in "一两兩" else 1.2
    elif word == "策":
        value = 1.4 if japanese else 2.7
    elif word == "决策" or word == "決策":
        value = 1.5

    if previous.endswith(("测", "測")) and word in ("验", "驗", "试", "試"):
        value = 2.7

    # Korean measure/side syllables, including their byte-split form.
    if word in ("측", "쪽"):
        value = 10.8 if pending and word == "측" else 2.25
    elif tail == "측".encode()[:2]:
        value = 6.5
    elif word == "층" and pending:
        value = 2.8

    # A few especially strong word-piece spelling responses.
    if previous.strip() == "Che" and word == "gg":
        value = -6.7
    if previous.endswith("c") and word == "è":
        value = 1.4
    if previous.endswith("コ") and word == "ツ":
        value = -3.5

    if word and set(word) == {"·"} and len(word) >= 2:
        value = -3.07 if decoration else -0.2
    if decoration and word and set(word) == {"^"} and len(word) >= 4:
        value = -4.89
    if first and word == "<|endoftext|>":
        value = -3.76

    japanese = japanese or bool(regex.search(r"\p{Script=Hiragana}|\p{Script=Katakana}", text))
    decoration = decoration and bool(word) and set(word).issubset({"^", "·"})
    return (doc, tail, text, japanese, decoration), float(value)

"""Approximate sparse responses to recognizable local text formats.

Commas in numeric brackets, conjunction commas and date metadata are
positive signals; quoted/negated code guards and string calls are negative.
There are also small rules for code annotations and formatting escapes.
Coefficients summarize training observations, not a full syntax parser.
The default is nearly zero.  A 160-character suffix resets per document.
"""
import re
from atoms import FULLWIDTH_DIGITS

READS = ()
MONTH = r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*'


def response(token, previous, text):
    word = previous.strip()
    lower = word.lower()
    value = -0.002

    if token in {',', '，'}:
        boundary = re.search(r'(?<!\w)' + re.escape(word) + r'$', text)
        if boundary and lower in {'but', 'or', 'and', 'if', 'then',
                                   'so', 'yet', 'whereas', 'thus', 'plus'}:
            weights = {'but': 4.3, 'or': 4.6, 'and': 2.8,
                       'if': 2.5, 'then': 1.8, 'so': 0.9,
                       'yet': 2.6, 'whereas': 2.5, 'thus': 0.25,
                       'plus': 1.1}
            value = weights[lower]
            if word.isupper():
                value *= 0.35
            elif word.islower() and lower not in {'whereas', 'thus'}:
                value *= 0.18
                if re.search(r';\s*\w+$', text):
                    value = 3.0
        elif word.isdigit():
            m = re.search(r'\[([0-9, ]*)$', text)
            if m:
                before = text[:m.start()]
                is_array = before.rstrip().endswith(('=', ':', '('))
                is_math = '$' in before[-80:] or '\\mapsto' in before
                first = 1.75 if is_array else 2.5 if is_math else 4.1
                decay = 0.2
                value = first * decay ** m[1].count(',')
            elif re.search(r'\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)'
                           r'\.?\s+\d{1,2}$', text):
                value = 0.7
            elif re.search(r"\bsed\s+-n\s+['\"]\d+$", text):
                value = 2.2
            elif token == '，' and set(word) <= FULLWIDTH_DIGITS:
                value = 0.65

    line = text.replace('\\n', '\n').rsplit('\n', 1)[-1]
    code_guard = line.strip().lstrip('+-').strip() in {'if', 'elif', 'while'}
    if lower in {'if', 'elif', 'while'}:
        start = token.lstrip()
        if start in {'[', '[['}:
            value = 10.0 if previous == 'if' else 6.3
        elif start in {'"', "'"} and code_guard:
            value = -8.8
        elif start.startswith('(!('):
            value = -3.4
        elif start.startswith('(!'):
            value = -1.9
        elif start == '(':
            value = -0.4
        elif start == '($':
            value = -1.4
        elif start == 'not' and code_guard:
            value = -0.9

    if token == ' at':
        if re.search(r"'\d{2}$", text):
            value = 12.8
        elif re.search(MONTH + r'\s+\d{1,2},?\s+\d{4}$', text):
            value = 2.5
    if token == ':' and (text == 'Title' or
                        text.endswith('<|endoftext|>Title')):
        value = 9.57
    if token == ' badges' and previous.strip() == 'bronze':
        value = 13.8
    if token and len(token) >= 2 and set(token) == {'·'}:
        value = 1.14

    # Numbered references and zero-padded paragraph labels.
    if len(token) == 1 and token.isascii() and token.isdigit():
        if token == '1' and previous == '>&':
            value = 1.63
        else:
            m = re.search(r'\[(\d*)$', text)
            if m:
                digits = m[1]
                if not digits:
                    bare = not previous.startswith(' ')
                    value = 0.2 if bare and int(token) >= 4 else -0.13
                elif len(digits) == 1 and int(digits) >= 3:
                    value = 0.5
                elif len(digits) == 1 and digits == '0':
                    value = -0.22
                elif len(digits) == 2 and digits.startswith('0'):
                    if int(token) >= 3:
                        value = 0.8
                    else:
                        value = 0.1 if token == '0' else -0.2

    # Section-sign red color escape; decimal character-class upper bound.
    if token == 'c' and previous.endswith('§'):
        value = 5.8
    if token == '9' and re.search(r'\[[0-8]-$', text):
        value = 2.4

    # String-manipulation calls, bitwise negation and Rust references.
    if previous in {'.split', '.replace', '.contains', '.endswith',
                    '.startswith'} and token.startswith(('("', "('")):
        value = -1.6
    if token == ' ~' and previous.strip() == '&':
        value = -5.5
    if token == 'mut' and previous.endswith('&'):
        value = 2.1
    if token == 'Header' and previous.rstrip().endswith('['):
        value = 3.2
    if token == 'test' and text.endswith('#['):
        value = 1.55
    if token.strip() in {'typeof', 'isset'} and re.search(r'\bif\s*\($|&&\s*$', text):
        value = -1.7
    if token == 'INFO' and previous.rstrip().endswith('['):
        value = 1.6
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        _, previous, text = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, text)
    return (doc, token, (text + token)[-160:]), float(value)

programs.haiku:
"""Layer 1, MLP down-projection, component 1539 (a sparse, mostly-silent feature).

It fires on a few recognisable spots in text and code, and is near 0 elsewhere:
  * the "at" in a forum timestamp such as "Feb 28 '13 at 23:" (very large);
  * a comma inside a bracketed citation or index list of numbers, as in "[23,24]";
  * a comma right after a sentence-opening connective: "But, " "And, " "Or, " "If, ";
  * the ":" of a "Title:" label that starts a document;
  * a run of middle dots used as filler.
It goes negative on the opening of a condition in code: a string literal or "(!" right
after "if" (for example `if "dnf" in ...`).
"""
import re

READS = ()

CONNECTIVE_VALUE = {"But": 4.2, "And": 4.8, "Or": 4.3, "Yet": 3.0, "If": 2.4,
                    "Then": 1.6, "Plus": 1.4, "but": 1.5, "So": 0.7, "and": 0.7}
MONTH_DAY = re.compile(r"(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]* \d{1,2},? \d{4}$")
YEAR_SHORT = re.compile(r"'\d\d$")
CITATION = re.compile(r"[a-z] \[\s*[1-9]\d*(\s*,\s*\d+)*$", re.IGNORECASE)
CONDITION_WORDS = {"if", "elif", "while"}
CODE_IF = re.compile(r"\bif \S{0,2}\s*$")
OPERATOR_WORDS = {"and", "or", "&&", "||", "==", "!=", "===", "!=="}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    prev = s[-2].strip() if len(s) > 1 else ""
    before = "".join(s[-12:-1])  # the text just before the current token
    value = 0.0
    if cur == " at" and YEAR_SHORT.search(before):
        value = 12.6
    elif cur == " at" and MONTH_DAY.search(before):
        value = 4.2
    elif cur == "," and prev in CONNECTIVE_VALUE:
        value = CONNECTIVE_VALUE[prev]
    elif cur == "," and prev.isdigit() and CITATION.search(before):
        value = 3.2
    elif cur == ":" and prev == "Title" and len(s) > 2 and "endoftext" in s[-3]:
        value = 9.5
    elif cur == "··":
        value = 1.1
    elif cur.strip() in ('"', "'", '\\"') and prev in CONDITION_WORDS:
        value = -6.0
    elif cur.strip() in ('"', "'", '\\"') and CODE_IF.search(before):
        value = -6.0
    elif cur in (" (!", " !(", " ~(", " (!("):
        value = -1.8
    return carry, float(value)

programs.sol:
"""Approximate structural formatting, especially transcript line breaks.

A newline's size depends on the preceding chat role or tool/thinking tag.
Tags themselves get small offsets. Fresh documents have character-shape
biases, with stronger negative responses for code openers and the colon
in an initial 'Title:' header. Repeated middle dots get a positive value.
Ordinary text stays near zero: its lexical variation is not modeled.
State resets at document boundaries.
"""
READS = ()

BREAK_AFTER = {
    'assistant': 0.35,
    'user': 0.12,
    '<tool_call>': 0.51,
    '<tool_response>': 0.42,
    '<think>': 0.34,
    '</think>': 0.35,
    '<|im_end|>': 0.09,
}
MARKERS = {
    '<|im_start|>': -0.027,
    '<|im_end|>': -0.045,
    '<think>': -0.075,
    '</think>': -0.012,
    '<tool_call>': -0.03,
    '</tool_call>': 0.032,
    '<tool_response>': -0.023,
    '</tool_response>': 0.044,
}
IMPORTS = {'using', 'package', 'import', 'export'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    token = prefix.token_strings[-1]
    value = 0.003
    if token in MARKERS:
        value = MARKERS[token]
    elif token.isspace() and '\n' in token:
        value = BREAK_AFTER.get(previous, 0.008)
    elif token and not token.strip('·') and len(token) >= 2:
        value = 0.95
    elif token == ':' and previous == 'Title' and position == 1:
        value = -2.15
    elif position == 0:
        text = token.strip()
        value = -0.06
        if text.isdecimal():
            value = 0.065
        elif token.isascii() and token.isalpha():
            value = -0.25 if token.isupper() else -0.16
        elif token.isalpha() and not token.isascii():
            value = 0.0
        if token in {'def', 'class'}:
            value = -1.3
        elif token in IMPORTS:
            value = -0.9
        elif token == 'int':
            value = -1.95
        elif token.startswith('#') or token.startswith('//'):
            value = -0.6
    return (doc, token, position), value

"""A sparse approximation to scientific notation and abstract-style wording.

Positive responses mark statistical comparisons, parentheses in formulas and
acronyms, biomedical terms, author-reporting phrases, and comparisons such as
'consistent with'. Translocations and powers-of-ten denominators are stronger.
The document's first token has a separate, mostly negative, shape-based baseline.
Most other tokens get a value near zero. State is only the recent text and the
position in the document; it is reset at each document boundary.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
ACADEMIC = set('study paper article work research project review report '
               'presentation course book dissertation thesis'.split())
REPORTING = set('show report describe demonstrate present propose conclude '
                'indicate suggest explain address discuss investigate'.split())
BIOLOGY = set('gene genetic genomic genome dna rna mrna protein tumor '
              'cancer cell neuron'.split())

@lru_cache(maxsize=4096)
def roots(word):
    return frozenset((word, *wordnet.base_forms(word)))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before, position = ('', 0) if first else carry[1:]
    token = prefix.token_strings[-1]
    s = token.strip()
    low = s.lower()
    prev = before.rstrip()
    words = re.findall(r'[A-Za-z]+', prev[-80:])
    last = words[-1].lower() if words else ''
    state = (doc, (before + token)[-120:], position + 1)

    if first:
        value = -0.289 - 0.398 * min(len(s), 12) / 12
        value += 0.013 * s.isascii()
        value -= 0.041 * (s.isalpha() and s.islower())
        value -= 0.063 * s.istitle()
        value += 0.208 * s.isupper()
        value += 0.155 * (token.startswith(' ') and s.isalpha())
        value += 0.316 * s.isdigit()
        value += 0.095 * (bool(s) and not any(c.isalnum() for c in s))
        value += 0.216 * any(c in s for c in '_./\\')
        return state, float(value)

    value = 0.002
    if '`' in s:
        value -= 0.024
    if s and set(s) == {'*'}:
        value -= 0.007
    if s and set(s) == {'·'}:
        value -= 0.356

    if s in ('=', '<', '>', '≤', '≥'):
        match = re.search(r'([A-Za-z]+)\s*$', prev)
        var = match.group(1) if match else ''
        value += {'p': 0.500, 'n': -0.058, 'r': 0.097}.get(var.lower(), 0)
        if len(var) == 1 and var.lower() not in ('p', 'n', 'r'):
            value += 0.019
        if re.search(r'\([nNrRB]\s*$', prev):
            value += 0.960
        if var.lower() == 'n' and token.startswith(' '):
            value += 0.234
        if var == 'B' and token.startswith(' '):
            value += 0.068
        if s == '<':
            value += 0.026

    if s == '(':
        attached = not token.startswith(' ')
        value += 0.185 * (attached and bool(prev) and prev[-1].isdigit())
        single_letter = re.search(r'(?<![A-Za-z])[A-Za-z]$', prev)
        value += 0.074 * bool(attached and single_letter)
        acronym = re.search(r'[A-Z]{2,}$', prev)
        value += 0.121 * bool(attached and acronym)
        value += 0.131 * bool(re.search(r'[/^*][0-9]+$', prev))
        # Parenthesized exponents in scientific denominators: /10(9).
        if re.search(r'/10$', prev):
            value += 2.0
        # t(...) names a chromosomal translocation, not an ordinary function.
