import re
import unicodedata

READS = ()
VERB_PARTICLES = frozenset((
    'an auf aus bei ein fest fort frei her heraus herein hin hinaus hinein '
    'los mit nach nieder um unter vor vorbei wahr weg weiter wieder zu '
    'zurück zusammen'
).split())


def activation(token, word):
    text = token.lstrip().lower()
    before = word.lower()
    if text == 'zu':
        if token[0].isspace() or not word:
            return -13.5
        return -15.6 if before in VERB_PARTICLES else -6.8
    if text == 'zum':
        return -2.0
    if text == 'zur':
        return -2.9
    if text.startswith('zu') and len(text) == 3:
        return -6.2
    if token.lower().startswith('u') and len(token) <= 4:
        if before.endswith('z'):
            if text.startswith('ung'):
                return 0.0  # German nominal suffix, not the zu fragment.
            if text in ('um', 'ur'):
                return -3.8
            if before[:-1] in VERB_PARTICLES:
                return -14.9
            if token == 'u':
                return -16.0 if word == 'Z' else -9.6
            return -6.5 if before == 'z' else -6.0
        if before.endswith('s'):
            if word[-1].isupper() and token in ('U', 'Us'):
                return -8.4  # Acronym ending SU, optionally pluralized.
            if len(token) == 1:
                return -4.3
            if len(token) == 2:
                return -1.1
    if len(token) == 1 and token.lower() != 'u':
        if unicodedata.normalize('NFD', token.lower())[0] == 'u':
            if before.endswith('z'):
                return -4.8
            if before.endswith('s'):
                return -1.6
    if text == 'su':
        if token != token.lower():
            return -2.1
        return -0.7 if token[0].isspace() else -4.2
    if 3 <= len(text) <= 4 and text.endswith(('su', 'zu')):
        return -3.0
    return -0.75 if text == 'too' else 0.0


