    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ''
    value = activation(token, word)
    tail = re.search(r'[^\W\d_]+$', (word + token)[-64:])
    return (doc, tail.group() if tail else ''), value

"""Local fraction and phrase patterns.

A digit starting a denominator responds especially strongly in halves,
quarters and eighths with an odd numerator. Unit fractions are strongest;
thirds and sixths have a much smaller response. These are text patterns,
not an arithmetic evaluator: the denominator may continue after this digit.
The phrase 'at first' is a separate strong trigger. Weaker digit-run
responses depend on the hundreds digit's parity and the tens digit modulo
four. This is a surface regularity, not a claim about arithmetic reasoning.
Other contexts are mostly zero; text state resets at document boundaries.
"""
import re

READS = ()

UNIT = {'2': 4.6, '3': .8, '4': 4.2, '6': 1.0, '8': 2.7}
ODD = {'2': 2.5, '3': .05, '4': 2.9, '6': .3, '8': 2.2}
SYMBOLIC = {'2': 1.2, '3': .05, '4': .9, '6': .1, '8': .3}


def decimal_response(digit, left):
    """The two preceding decimal places give a weaker periodic response."""
    m = re.search(r'([0-9])([0-9])$', left)
    if not m:
        return .04
    hundreds, tens = map(int, m.groups())
    if hundreds % 2:
        if tens % 4 == 0:
            return .35 if digit == '2' else 1.25
        if tens % 4 == 1:
            return .75 if digit == '2' else .33
        if tens % 4 == 3 and digit == '2':
            return -.2
    elif tens % 4 == 0:
        return -.23
    return .04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    left = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0

    if word in ('first', 'night', 'any'):
        at = re.search(r'\bat\s*$', left, re.I)
        if word == 'first':
            value = -.25
            if at:
                value = 8.6 if at.group().startswith('At') else 7.3
        elif word == 'night':
            value = .87 if at else -.10
        else:
            value = .16 if at else -.03

    elif token in UNIT:
        value = decimal_response(token, left) if token in ('2', '4') else 0.0
        # Slash notation, or the numerator/denominator boundary in LaTeX.
        m = re.search(r'(\d+|[A-Za-z]|\))\s*/\s*\(?\s*$', left)
        if not m:
            m = re.search(r'\{([^{}]*)\}\s*\{\s*$', left)
        if m:
            numerator = m.group(1).strip()
            value = SYMBOLIC[token]
            if numerator.isascii() and numerator.isdigit():
                n = int(numerator)
                value = .05
                if n == 1:
                    value = UNIT[token]
                elif n % 2:
                    value = ODD[token]
                    if n == 3 and token in ('2', '4'):
                        value = 3.7
            if re.search(r'/\s*\(\s*$', left):
                value *= .7
        elif re.search(r'/\s*\(?\s*$', left):
            value = 1.3 if token == '2' else .1

    return (doc, (left + token)[-80:]), value

