    if w == 'side' and (hyphen or low.startswith(' ')):
        return 3.0 if word in {'server', 'client'} else -0.1
    if hyphen:
        if w in CAUSAL:
            return 4.1 if w == 'mediated' else 3.3
        if w in AGENTIVE:
            return 0.4 if word in {'co', 'auto', 'self', 'well'} else 2.35
        if w in RESTRICTIVE:
            return 0.45 if word == 'time' else 2.1
        if w in RELATIONAL:
            return 0.25 if word in {'co', 'self', 'well'} else 1.35
        if w in BASIS_FORM_CONTENT:
            return 0.85
        if w in {'wide', 'era'}:
            return 3.0
        if w in {'style', 'grade'}:
            return 1.8 if word not in SCALAR else 0.0
        if w == 'scale':
            return 0.75
        if w == 'free':
            return 0.25
        if w == 'to':
            return 0.45
    if low.startswith(' ') and w in CAUSAL:
        return 1.4 if noun_like(word, before) else 0.0
    return POSTPOSITIONS.get(t, 0.0)

