READS = ()
LANGUAGES = ('fr', 'it', 'es', 'pt', 'ro', 'en', 'de',
             'nl', 'sv', 'da', 'nb', 'id', 'tr')

@lru_cache(maxsize=20000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language_weights(text):
    words = re.findall(r"[^\W\d_]+", text.lower())[-24:]
    scores = [0.0] * len(LANGUAGES)
    total = 0.0
    for age, word in enumerate(reversed(words)):
        if len(word) < 2:
            continue
        weight = 0.93 ** age
        values = frequencies(word)
        if max(values) < 2:
            continue
        total += weight
        for i, value in enumerate(values):
            scores[i] += weight * value
    if total:
        scores = [s / total for s in scores]
    top = max(scores)
    weights = [math.exp(4.0 * (s - top)) for s in scores]
    total = sum(weights)
    p = [w / total for w in weights]
    # A diagnostic nearby word can reveal a borrowed French/Italian phrase.
    # Avoid short function words such as English/Italian "per".
    if words and (len(words[-1]) >= 4 or not words[-1].isascii()):
        values = frequencies(words[-1])
        top = max(values)
        local = [math.exp(4 * (v - top)) for v in values]
        total = sum(local)
        local = [v / total for v in local]
        i = max(range(len(local)), key=local.__getitem__)
        if i in (0, 1) and local[i] > 0.8 and top >= 2:
            boosted = max(p[i], 0.8 * local[i])
            scale = (1 - boosted) / max(1e-9, 1 - p[i])
            p = [boosted if j == i else v * scale
                 for j, v in enumerate(p)]
    return p


