DECL_WORDS = {"def", "fn", "func", "public", "private", "protected", "static", "void"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    return None, (-0.2 if token in DECL_WORDS else 0.0)

"""Layer 1 MLP down-projection component 1556: a weak, mostly diffuse signal.

What it does (rule-based, fit on training text; most of its variance is not captured):
- First token of a document. The model resets attention there, so the component's value
  depends only on that token. Four cases:
  * a small English function word (the, of, and, to, a, in, with, ...): negative;
  * a token that opens code or markup (package, import, #include, //, an indented block):
    strongly positive;
  * a digit: slightly negative;
  * anything else: slightly positive if it starts a fresh word or punctuation mark, about
    zero if it starts with a leading space (the document begins mid-sentence).
- Mid-document: the word "in" written in another language (en, em, в, w and capitals):
  negative. Every other position: 0.
"""

READS = ()

FUNCTION_WORDS = frozenset({" the", " of", " and", " to", " a", " in", " for", " with", " on",
                            " at", " that", " by", " an", " from", " or", " as"})
CODE_OPENERS = frozenset({"package", "import", "#include", "//", "   ", "    ", "#", "using",
                          "assert", "<?", "/*", "@"})
IN_OTHER_LANGUAGES = frozenset({" en", " em", " в", " w", " В", "В", "En", " En", "Em", " Em"})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        if token in FUNCTION_WORDS:
            value = -0.2
        elif token.strip() in CODE_OPENERS or token in CODE_OPENERS:
            value = 0.56
        elif token[:1].isdigit():
            value = -0.08
        elif token.startswith(" "):
            value = 0.015
        else:
            value = 0.084
    elif token in IN_OTHER_LANGUAGES:
        value = -0.157
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A mixed structural-token detector.

Strong positive responses mark code conditionals and logical operators, the
first dash after a colon-led introduction, first numbered items, standard
C++ namespace separators, method chaining, and GitHub host names. Smaller
rules cover five, tooth/teeth spellings, French/Swedish negation, headings,
tool tags and initial escaped whitespace. State remembers the current line and
previous nonempty line, and resets at document boundaries.
"""
import re

READS = ()
ESCAPES = re.compile(r'\\+[nrt]')
LINE_START = re.compile(r'\s*(?:[+-]\s*)?(?:\d+\s*[:|\t]\s*)?')


def predict(s, line, lastline, condition, position):
    w = s.strip()
    start = not line.strip() or LINE_START.fullmatch(line) is not None
    intro = re.search(r':(?:\*\*)?\s*$', lastline) is not None
    if w in ('while', 'return', 'assert') and start:
        return 0.014, True
    if w in ('if', 'elif'):
        if start or re.search(r'(?:else|`|\{%?-?|<!--\[)\s*$', line):
            if '\t' in s + line:
                return 0.93, True
            indent = len(line) + len(s) - len(s.lstrip())
            return (1.09 if indent >= 8 else 0.90), True
        return 0.008, False
    if w in ('AND', 'OR') and (start or '=' in line):
        return 0.59, False
    if w in ('and', 'or', 'not'):
        if condition:
            return {'and': 1.21, 'or': 0.93, 'not': 0.65}[w], False
        return {'and': 0.002, 'or': 0.019, 'not': 0.034}[w], False
    if w in ('&&', '||', '!', '&&!', ')&&') and s != '!':
        comparison = bool(re.search(r'[<>=]|\b(?:if|while)\b', line))
        if comparison or condition or start or re.search(r'\breturn\s*$', line):
            return (0.77 if w == '||' else 0.74 if w == '!' else 1.20), False
        return (0.30 if w == '&&' else 0.03 if w == '||' else -0.03), False
    if w == '::':
        return (1.15 if re.search(r'\bstd$', line) else 0.045), False
    if s == '.com' and re.search(
        r'(?:^|[^\w.-])(?:github|raw\.githubusercontent)$', line
    ):
        return 2.34, False
    if w in ('-', '–', '—', '*', '•', '●', '▪', '◦', '·'):
        if start:
            if w in ('-', '–', '—'):
                return (1.08 if intro else 0.92 if w == '–' else 0.31), False
            if w == '*':
                comment = lastline.lstrip().startswith(('/*', '*'))
                return (0.10 if comment else 0.88 if intro else 0.24), False
            return (0.78 if intro else 0.12), False
        return (0.19 if w in ('•', '●', '▪', '◦') else 0.02), False
    if (w == 'item' and line.endswith('\\')) or (w == 'o' and start and intro):
        return 1.15, False
    if w == '.':
        if re.fullmatch(r'\s*\d{1,3}', line):
            return (0.57 if line.strip() == '1' else 0.043), False
        if position == 0 and s == ' .':
            return 3.27, False
        return (0.85 if start and (len(line) >= 2 or s.startswith(' ')) else 0.003), False
    if w.endswith('.') and w[:-1] and all(c in '()[]\'"}' for c in w[:-1]):
        if '()' in w:
            return 0.87, False
        quoted_call = any(c in w for c in '\'"') and any(c in w for c in ')]')
        if quoted_call:
            return 0.80, False
        code = '$' not in line and bool(re.search(
            r'\b(?:return|const|let|var)\b|[=;{}]|\w\.\w|\w\(', line
        ))
        return (0.14 if code else 0.014), False
    if w in ('()->', '")->', "')->"):
        return 0.59, False
    if w in ('(&', '(!', '(*'):
        return 0.69, False
    if w == '&':
        return (0.66 if re.search(r'[,=(]\s*$|:=\s*$', line) else 0.12), False
    if s == '5':
        if line and line[-1].isalpha():
            return 0.44, False
        return (-0.18 if re.search(r'\d\.$', line) else 0.07), False
    if w.lower() in ('five', 'fives'):
        return 0.16, False
    if w.lower() in ('ive', 'ives') and re.search(r'\bf$', line, re.I):
        return 1.88, False
    if (line + s).lower().endswith(('tooth', 'teeth')):
        return 1.0, False
    if s in (' pas', ' inte'):
        return 0.68, False
    if w and set(w) == {'#'}:
        return -0.08, False
    if s in ('<tool_call>', '</tool_call>'):
        return (-0.14 if s == '<tool_call>' else 0.14), False
    if s in (r'\n', r'\t') and (position == 0 or (position == 1 and line == '\t')):
        return (2.29 if s == r'\n' else 3.98), False
    return -0.002, False


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, 0)
    _, line, lastline, condition, position = carry
    value, new_condition = predict(s, line, lastline, condition, position)
    condition = condition or new_condition
    text = ESCAPES.sub(lambda m: {'n': '\n', 'r': '\r', 't': '\t'}[m[0][-1]], line + s)
    if '\n' in text:
        parts = text.split('\n')
        for part in parts[:-1]:
            if part.strip():
                lastline = part
        line, condition = parts[-1], False
    else:
        line = text
    return (doc, line[-256:], lastline[-256:], condition, position + 1), value

programs.haiku:
"""Boolean tests in source code (layer 1, MLP output unit 1557).

What it does: this unit fires on the words and symbols that open or join a true/false
test in code, and it is nearly silent on the same words in ordinary prose.

Main triggers, with the rough activation they reach:
- `if` / `elif` that starts a statement (after indentation): about 1.0.
- `if` in the middle of a line of code: about 0.5. In English prose, "if" is near 0.
- `&&`, `||`, `!` inside an `if` condition: about 1.5. Outside one: about 0.5.
- Python `and`, `or`, `not` inside a condition: about 0.3. In prose they stay at 0.
- SQL/upper-case `AND`, `OR`: about 0.5.
Smaller, separate habits:
- `.com` right after `github` (as in Go imports and URLs): about 1.8.
- A method chain token right after a call, `().`, `").`, `()->`: about 1.0.
- C++ `::` (as in `std::endl`): about 0.3.
- A markdown bullet `-` or `•` starting a line: about 0.4 and 0.15.
- The digit 5 when it is part of a name (`md5`, `f5`): about 0.4; otherwise 0.1.

Each strength is multiplied by SCALE, a least-squares fit to the real activations, so the
raw predictions are on the component's own scale. The state carried between tokens is
whether an `if`/`elif` has appeared earlier on the current line."""

READS = ()

SCALE = 0.7
CODE_CHARS = set("(){}[];=<>")
IF_WORDS = {"if", "elif"}
OPERATORS = {"&&", "||", "!", "(!"}
CONNECTIVES = {"and", "or", "not"}
UPPER_CONNECTIVES = {"AND", "OR"}
CHAIN_TOKENS = {"().", "\").", "()->"}


def step(carry, prefix, upstream):
    in_test = bool(carry)  # an if/elif has appeared earlier on this line
    token = prefix.token_strings[-1]
    word = token.strip()
    before = "".join(prefix.token_strings[-12:-1])
    line = before.split("\n")[-1]
    line_start = line.strip() == ""
    in_code = in_test or any(ch in CODE_CHARS for ch in line)

    value = 0.0
    if word in IF_WORDS:
        value = 1.0 if line_start else (0.5 if in_code else 0.1)
    elif word in OPERATORS:
        value = 1.5 if in_test else 0.5
    elif word in CONNECTIVES and in_test:
        value = 0.3
    elif word in UPPER_CONNECTIVES:
        value = 0.5
    elif token == ".com" and "github" in before[-20:]:
        value = 1.8
    elif word in CHAIN_TOKENS:
        value = 1.0
    elif word == "::":
        value = 0.3
    elif word == "-" and line_start:
        value = 0.4
    elif word == "•" and line_start:
        value = 0.15
    elif word == "5":
        value = 0.4 if before[-1:].isalpha() else 0.1

    if "\n" in token:
        in_test = False
    if word in IF_WORDS:
        in_test = True
    return in_test, SCALE * value

programs.sol:
"""Approximate an h/k spelling response, not a hacking-topic response.

Hack/hoc, kick and hunt spellings give negative peaks; short consonant
continuations of H often give positive ones. These rules also recognize
split spellings, but exclude ordinary h digraphs such as th and ch.
Document starts get a separate coarse formatting-dependent baseline.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    first = len(prefix.token_ids) == 1 or (
        prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if first else prefix.token_strings[-2]
    s, p = text.lower(), previous.lower()
    word = s.lstrip()
    value = 0.001

    if word.startswith('hack'):
        value = -7.7 if word in ('hack', 'hacks', 'hacked') else -4.2
    elif word == 'hoc':
        value = -8.8 if text[:1].isspace() else -4.8
    elif word.startswith('kick') and not word.startswith('kickstart'):
        value = -2.2 if word in ('kicked', 'kicks') else -3.7
    elif word.startswith('hunt'):
        value = -0.8 if word.startswith('hunter') else -2.1
    elif re.match(r'h(?:ic|ike|iking|ock)', word):
        value = -1.8
    elif word.startswith('học'):
        value = -4.4

    # A final h in th/ch/sh/ph/gh/wh is not an independent h onset.
    h = p.endswith('h') and not p.endswith(
        ('ch', 'sh', 'th', 'ph', 'gh', 'wh'))
    if s[:1].isalpha() and h:
        if s.startswith('ack'):
            value = -11.8
        elif s.startswith('oc') and not s.startswith('ock'):
            value = -8.8 if s == 'oc' else -4.7
        elif s.startswith(('ock', 'ike', 'iking', 'ick')):
            value = -3.8
        elif s.startswith(('unt', 'unc')):
            value = -5.5
        elif re.match('[aeiou]+[ck]', s):
            value = -1.6
        elif p.endswith('kh') and s == 'mer':
            value = 5.3
        elif s == 'bs':
            value = 6.6
        elif len(s) <= 2 and s.isalpha() and not re.search('[aeiou]', s):
            if s.startswith('k'):
                value = 5.0 if s.endswith('s') else 3.0
            elif s.startswith('c'):
                value = 1.0 if s.endswith('s') else -2.0
            elif s[0] in 'fhps' and s[-1] in 'str':
                value = 2.7
            elif s[0] in 'mg' and s.endswith('s'):
                value = 1.8
    elif s[:1].isalpha() and re.search(r'(?<![a-z])k$', p):
        if s.startswith('ick'):
            value = -5.0
        elif s == 'ops':
            value = 4.0
        elif s == 'bs':
            value = 3.4
        elif re.match('[aeiou]+[ck]', s):
            value = -1.7

    # Related non-Latin spellings, and the guest graph used in 黑客 (hacker).
    if text == 'ック':
        value = {'ハ': -11.4, 'キ': -3.5}.get(previous[-1:], value)
    if p.endswith('х') and s.startswith('ач'):
        value = -4.6
    if text in ('客', '黑客'):
        value = -2.0

    if first:
        if word.startswith('hack'):
            value = -11.5
        elif value == 0.001:
            if text.startswith('//'):
                value = 2.7
            elif text.startswith(('"""', "'''", '/**')):
                value = 2.1
            elif text == '<|endoftext|>':
                value = 3.7
            elif text.startswith('<|'):
                value = -0.16
            elif text.lstrip().startswith('#'):
                value = 1.0
            elif text.strip().isdigit():
                value = 0.45
            elif text.isspace():
                value = 0.38
            else:
                value = 0.3 if text.isascii() else 0.2
    elif text == ':' and previous == 'Title':
        second = len(prefix.token_ids) == 2 or (
            prefix.document_ids[-3] != prefix.document_ids[-2])
        if second:
            value = -6.1
    return None, float(value)

"""Surface patterns for preferable methods, optimization, and estimation.

'Best/easiest/only way' is positive, as is the 'to' following 'way'.
Optimization and estimation stems also respond. Contrasting constructions
('best of', 'opt out', 'factor out'), selected change-verb + 'to' phrases,
and newly reached opto- stems are negative. Unmatched tokens return zero. The bounded text carry resets at document boundaries. This deliberately
omits many less systematic, language-specific word-fragment responses.
"""
import re

READS = ()
METHODS = set('method methods strategy strategies means idea incentive '
              'opportunity opportunities chance place time moment'.split())
READY = {'ready', 'eager', 'excited', 'wait'}
EFFICIENT_SUPERLATIVES = set('easiest fastest quickest simplest safest '
                             'smartest shortest cheapest'.split())
GOOD = {'good', 'great', 'easy', 'convenient'}
CHANGE = re.compile(r'(?:choos(?:e[sn]?|ing)|chose|chosen|elect(?:ed|s|ing)?|'
                    r'switch(?:ed|es|ing)?|convert(?:ed|s|ing)?|'
                    r'adapt(?:ed|s|ing)?|reduc(?:e[sd]?|ing)|'
                    r'modif(?:y|ies|ied|ying)|promot(?:e[sd]?|ing))$')


def manner(words):
    """Strength of an immediately preceding evaluative modifier."""
    w = words[-1] if words else ''
    if w == 'best':
        return 6.5
    if w in EFFICIENT_SUPERLATIVES:
        return 5.2
    if w in {'only', 'better'}:
        return 3.25 if w == 'only' else 2.1
    if w in {'effective', 'efficient'}:
        superlative = len(words) > 1 and words[-2] in {'most', 'least'}
        return 4.3 if superlative else 2.3
    return 1.5 if w in GOOD else 0.0


def response(tail, token):
    w = token.strip().lower()
    words = re.findall(r'[a-z]+', tail.lower())
    p = words[-1] if words else ''
    if w in {'way', 'ways'}:
        return manner(words)
    if w in {'to', '-to', '_to'}:
        if p in {'way', 'ways'}:
            modifier = words[-2] if len(words) > 1 else ''
            if modifier == 'better':
                return 3.4
            if modifier == 'only' or modifier in GOOD:
                return 2.6
            return 1.45 + 0.57 * manner(words[:-1])
        if p in METHODS or p in READY:
            return 0.6
        if p in {'best', 'better', 'prior'}:
            return {'best': -1.35, 'better': -0.6, 'prior': -0.3}[p]
        if CHANGE.fullmatch(p) or p.endswith('ifies'):
            return -0.9
    if w in {'out', '-out', 'in', '-in'} and p == 'opt':
        return -7.0 if w.endswith('out') else -4.5
    if w in {'out', '-out'}:
        if p == 'factor':
            return -6.0
        if p.startswith('filter'):
            return -3.2
        if p.startswith(('cancel', 'rule')):
            return -1.2
    if p == 'best' and w in {'of', '-of'}:
        return -4.0
    if p == 'better' and w == 'than':
        return -0.9
    if p == 'best' and w in {'practice', 'practices'}:
        return 3.2
    if w == 'possible' and manner(words):
        return 1.5
    if w == 'opt' and token[:1].isspace():
        return -1.0
    # Reassemble stems split across tokens, e.g. opt + imal.
    match = re.search(r'[a-z]+$', (tail + token).lower())
    full = match.group() if match else ''
    if full.startswith('opto') and not p.startswith('opto'):
        return -4.5
    if full.startswith(('optim', 'ottim', 'unoptim', 'suboptim')):
        if full in {'optim', 'ottim'}:
            return 0.7
        if full.endswith(('ization', 'isation', 'izations', 'isations')):
            return 1.7
        if full.endswith('ally'):
            return 1.3
        if full.endswith('imal'):
            return 1.0 if w == full else 2.4
        return 2.2
    if full.startswith(('estimat', 'overestimat', 'underestimat')):
        return 0.6 if full.endswith(('estimated', 'estimates')) else 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(tail, token)
    return (doc, (tail + token)[-100:]), value

programs.haiku:
"""The 'best way to' component.

Fires on the words of a "best method" phrase: the noun "way"/"ways" after a
superlative or evaluative word ("the best way", "fastest way", "only way",
"better way"), the "to" that follows such a phrase, and optimisation words
("optimize", "optimal", "optimisation", Russian оптимизировать). Also positive
on "of" after "estimate/estimation/optimization".
Negative on idioms where the same words mean something else: "best of",
"opt out", "factor out", "filtered out", "object to", "switch to".
Everything else predicts 0; the diffuse small activations are not modelled.
"""
READS = ()

BEST = {"best", "fastest", "easiest", "quickest", "simplest", "cheapest", "safest"}
EVALUATIVE = BEST | {"only", "better", "smarter", "smartest", "efficient",
                     "most", "optimal", "ideal", "easier", "quicker"}
METHOD_NOUNS = {"means", "opportunity", "chance", "approach", "method", "methods",
                "technique", "techniques", "time", "ready", "eager"}
TO_VERBS = {"switch", "object", "simplify", "simplifies", "resolves", "default",
            "customized", "advanced", "updates", "prefers", "choose", "promoted"}
OUT_VERBS = {"opt", "factor", "filter", "filtering", "filtered", "leave", "rule", "cut", "left", "timed"}
OPTIM_WEIGHT = 2.5
OUT_OTHER = 0.0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = len(toks) - 1
    s = toks[t]
    new_doc = t == 0 or docs[t - 1] != docs[t]

    # the word being typed, letters only, carried from the previous token
    cut = max((i for i, c in enumerate(s) if not c.isalpha()), default=-1)
    if cut >= 0:
        word = s[cut + 1:].lower()
    else:
        word = ("" if new_doc or carry is None else carry) + s.lower()

    cur = s.strip().lower()
    prev = "" if new_doc else toks[t - 1].strip().lower()
    prev2 = "" if (new_doc or t < 2 or docs[t - 2] != docs[t]) else toks[t - 2].strip().lower()

    if word.startswith(("optim", "оптим")) and not word.startswith("optimist"):
        value = OPTIM_WEIGHT
    elif cur in ("way", "ways"):
        value = 6.0 if prev in BEST else (4.0 if prev in EVALUATIVE else 0.0)
    elif cur == "to" and prev in ("way", "ways"):
        value = 5.0 if prev2 in BEST else (3.0 if prev2 in EVALUATIVE else 1.0)
    elif cur == "to" and prev in METHOD_NOUNS:
        value = 0.5
    elif cur == "to" and prev in TO_VERBS:
        value = -2.0
    elif cur == "of" and prev == "best":
        value = -4.0
    elif cur == "out" and prev in OUT_VERBS:
        value = -4.0
    elif cur == "out":
        value = OUT_OTHER
    elif cur == "of" and prev.startswith(("estim", "optim")):
        value = 1.5
    else:
        value = 0.0
    return word, float(value)

programs.sol:
"""A negative detector for non-Latin-looking capital Greek math letters.

Recognize both written characters and TeX names, including names or UTF-8
characters split across tokens. Greek prose is much weaker than math use.
There are smaller positive responses at some programming type declarations,
and a modest document-initial response. These are approximate amplitudes,
not a reconstruction of the model's hidden layers.
"""
import re
import unicodedata as ud

READS = ()

# Letter name: (TeX command, written capital). Latin-looking Greek capitals
# such as Alpha and Beta do not have the large negative response.
LETTERS = {
    'Gamma': (-5.8, -4.1),
    'Delta': (-3.9, -2.6),
    'Theta': (-3.5, -2.6),
    'Lambda': (-5.6, -3.3),
    'Xi': (-4.7, -4.2),
    'Pi': (-7.8, -4.6),
    'Sigma': (-4.7, -1.4),
    'Phi': (-4.5, -3.3),
    'Psi': (-4.1, -2.7),
    'Omega': (-5.0, -2.6),
    'Upsilon': (-5.0, 0.0),
}
SYMBOLS = {'∆': -4.25, '⌬': -6.0}


def unfinished_utf8(raw):
    """Keep only an unfinished character, never earlier complete characters."""
    for n in range(1, min(4, len(raw)) + 1):
        lead = raw[-n]
        width = (2 if 0xC2 <= lead <= 0xDF else
                 3 if 0xE0 <= lead <= 0xEF else
                 4 if 0xF0 <= lead <= 0xF4 else 0)
        if width:
            return raw[-n:] if n < width else b''
    return b''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_bytes[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        recent, pending, first, repeating = '', b'', raw, True
    else:
        _, recent, pending, first, repeating = carry
        repeating = repeating and raw == first
    text = (pending + raw).decode('utf-8', 'ignore')
    next_pending = unfinished_utf8(pending + raw)
    value = 0.3 if initial else 0.0

    # A document consisting only of decorative leaders or carriage returns.
    if repeating and text and set(text) <= set('·^'):
        value = 1.57
    elif repeating and text and set(text) == {'\r'}:
        value = 2.25

    joined = recent + text
    command = re.search(r'\\([A-Za-z]+)$', joined)
    if command and text and text[-1].isalpha():
        name = command[1]
        if name in LETTERS:
            value += LETTERS[name][0]
            if recent and recent[-1].isalpha():
                value *= 1.3  # completing a split command name
        elif name == 'xi':
            value -= 1.3 if recent.endswith('x') else 0.8
        elif name in {'Large', 'LARGE', 'Huge', 'huge'}:
            value -= 4.0
        elif name == 'Sq':
            value -= 1.2
    elif text.strip() in LETTERS and recent.endswith('\\['):
        value -= 1.8  # Mathematica's \[Lambda] style

    for ch in text:
        name = ud.name(ch, '')
        if name.startswith('GREEK CAPITAL LETTER '):
            letter = name.removeprefix('GREEK CAPITAL LETTER ').title()
            if letter == 'Lamda':
                letter = 'Lambda'
            if letter in LETTERS:
                amplitude = LETTERS[letter][1]
                if pending and letter in {'Lambda', 'Xi', 'Phi', 'Omega'}:
                    amplitude -= 1.2
                if raw.startswith(b' ') and letter in {'Gamma', 'Delta'}:
                    amplitude -= 0.3
                greek = sum('GREEK' in ud.name(c, '') for c in recent)
                letters = sum(c.isalpha() for c in recent)
                if greek >= 5 and greek > 0.65 * letters:
                    amplitude *= 0.2
                value += amplitude
        elif ch in SYMBOLS:
            value += SYMBOLS[ch]

    if next_pending == b'\xce':
        value -= 0.2

    # Three easily recognized programming roles, not arbitrary class names.
    word = text.strip()
    if word == 'Solution' and recent.rstrip().endswith('class'):
        value += 5.9
    elif word == 'Exception' and recent.rstrip().endswith('except'):
        value += 2.2
    elif word == 'Self':
        value += 0.7

    return (doc, joined[-64:], next_pending, first, repeating), float(value)

"""Approximate a Chinese verb-complement boundary detector.

The current token's grammatical family supplies a baseline and a gain.
The preceding token's fraction of CC-CEDICT senses containing "to ..." gives
its verb score, with a bonus for one-character verbs. Unknown whole words
back off to a dictionary suffix with half strength. This is not a parser.
Unrecognized current tokens predict zero.
Runs of middle dots have a separate negative punctuation response.
"""
from functools import lru_cache
import re
import regex
import cedict

READS = ()

FAMILIES = {
    'perfective': ('了',),
    'progressive': ('着', '著'),
    'experience': ('过', '過'),
    'locative': ('在',),
    'path_relation': tuple('到给給向往朝自'),
    'result': tuple('成住完掉好死满滿足紧緊清懂见見定倒破碎散'
                    '中亮尽盡匀勻走远遠'),
    'direction': tuple('上下进進出回起开開去来來入'),
    'degree': ('得',),
    'negative': ('不',),
    'attributive': ('的',),
    'count_phrase': ('一个', '一個', '一', '一种', '一種', '一句'),
}
TAILS = {'来', '去', '來', '了', '了一', '了一个', '一个', '一個',
         '一', '起来', '下去', '上来', '下来', '的', '大家'}
POTENTIAL_RESULTS = set('住下了到起动完开出過过')

# (Baseline, verb-score gain) for each grammatical family.
PARAMETERS = {
    'degree': (0.24, 0.64),
    'direction': (-0.06, 1.40),
    'experience': (0.35, 1.75),
    'path_relation': (0.08, 1.18),
    'locative': (-0.14, 1.40),
    'negative': (0.05, 0.42),
    'potential': (0.41, 0.51),
    'count_phrase': (0.07, 0.04),
    'perfective': (0.77, 0.56),
    'progressive': (1.32, 0.86),
    'attributive': (-0.04, 0.17),
    'result': (-0.02, 0.75),
}

@lru_cache(maxsize=8192)
def family(text):
    # Positive/negative potential complements, such as 得起 and 不住.
    if len(text) > 1 and text[0] in '不得':
        if text[1:] in POTENTIAL_RESULTS:
            return 'potential'
    for name, words in FAMILIES.items():
        if text in words:
            return name
    for name in ('perfective', 'progressive', 'experience',
                 'direction', 'result', 'path_relation'):
        for word in FAMILIES[name]:
            if text.startswith(word) and text[len(word):] in TAILS:
                return name
    return None

@lru_cache(maxsize=8192)
def verb_strength(text):
    if not regex.search(r'\p{Script=Han}', text):
        return 0.0
    text = text.strip()
    glosses = cedict.glosses(text)
    whole_word = bool(glosses)
    if not glosses:
        for length in (3, 2, 1):
            glosses = cedict.glosses(text[-length:])
            if glosses:
                break
    verbs = sum(bool(re.search(r'\bto [a-z]+', gloss))
                for gloss in glosses)
    share = verbs / max(1, len(glosses))
    strength = 0.83 * share
    if verbs:
        strength += 0.56 * (len(text) == 1) - 0.06
    return strength if whole_word else 0.5 * strength


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if len(text) >= 2 and set(text) == {'·'}:
        return None, -1.53
    name = family(text)
    if name is None:
        return None, 0.0
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    strength = verb_strength(previous)
    base, gain = PARAMETERS[name]
    return None, float(base + gain * strength)

programs.haiku:
"""Verb-complement particles: a Chinese verb-complement particle (aspect marker or
directional/resultative complement) right after a verb character fires the component.
Strength depends on the particle: aspect markers strongest, a few complements near zero."""
READS = ()

ASPECT = set("着著了過过")            # aspect markers after a verb: 了 着 过
RESULT = set("起到完住掉遍尽盡下出好")  # directional / resultative complements
WEAK = set("上进進去回向给給死清")    # weaker complements
ZERO = set("来來不开開成入")          # rarely fire


def _cjk(s):
    return len(s) > 0 and "一" <= s[0] <= "鿿"


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    if not (_cjk(cur) and _cjk(prev)):
        return None, 0.0
    c = cur[0]
    if c in ASPECT:
        v = 1.0
    elif c in RESULT:
        v = 0.8
    elif c in WEAK:
        v = 0.4
    else:
        v = 0.0
    return None, float(v)

programs.sol:
"""A local phrase-completion signal.

Positive responses favor limiting/quantitative modifiers after prepositions
('in exactly', 'for just', 'at no'). Negative responses include partitive
pronouns ('of them'), familiar evidence/use phrases, and a few time idioms.
This approximation also has small lexical, punctuation and document-start
corrections. It only remembers the previous token, not the full sentence.
"""
READS = ()

PREPOSITIONS = {'in', 'on', 'at', 'of', 'for', 'to', 'from', 'with',
                'by', 'under', 'over', 'within', 'after', 'before'}
SUBJECTS = {'i', 'you', 'we', 'they', 'he', 'she', 'it'}
INTENSIFIERS = {'very', 'most', 'highly', 'extremely', 'particularly'}
FREQUENCY = {'widely', 'commonly', 'often', 'frequently', 'extensively'}
PARTITIVES = {'them': -1.38, 'you': -.84, 'us': -.34, 'which': -.52,
              'whom': -.56, 'this': -.06, 'these': -.20, 'those': -.13,
              'it': -.20}
LIMITERS = {'no': .03, 'about': .03, 'just': .06, 'only': .02,
            'either': .19, 'exactly': .25, 'precisely': .36}
PREP_LIMITERS = {'no': .62, 'about': .65, 'just': .88, 'only': .52,
                 'either': .48, 'exactly': .61, 'precisely': .10}


def response(p, w, raw, position):
    value = .001
    # Small word-class biases, before applying the stronger phrase effects.
    if w in {'known', 'shown', 'used'}:
        value -= {'known': .20, 'shown': .19, 'used': .09}[w]
        if p in FREQUENCY or p == 'ly':
            value -= .85 if w == 'used' else .59
        if p in {'well', 'best', 'as'}:
            value -= {'known': .80, 'shown': .51, 'used': .15}[w]
    if w == 'citizenship':
        value += .62
    if w in {'concern', 'concerns', 'concerned', 'interested', 'interests',
             'needs', 'wants', 'needed', 'wanting'}:
        value -= .15
    if w in {'says', 'said', 'called', 'referred', 'written'}:
        value -= .10
    if w in {'common', 'important', 'necessary', 'unique', 'distinct'}:
        value -= .08
    if w in {'same', 'similar', 'full', 'main', 'great', 'right'}:
        value += .07
    if w == 'want':
        value -= .08
        if p in SUBJECTS or p in {'really', 'still'}:
            value -= .40
        if p in {'to', 'may', 'might', 'would'}:
            value += .51
    if p == 'of':
        value += PARTITIVES.get(w, 0.)
    if w in LIMITERS:
        value += LIMITERS[w]
        if p in PREPOSITIONS:
            value += PREP_LIMITERS[w]
            value += .55 if p == 'at' else -.40 if p == 'with' else 0.
        if w == 'just' and p in {'than', 'not', 'beyond'}:
            value += .40
    if p == 'the':
        value += {'same': .06, 'right': .13, 'first': .07, 'main': .18,
                  'beginning': -.53, 'moment': -.23}.get(w, 0.)
    if p == 'at':
        if w in {'a', 'an', 'one'} or raw.isspace():
            value += .23
        if w in {'home', 'present'}:
            value -= .87
        if w in {'room', 'high', 'higher', 'similar'}:
            value += .72
    if p == 'in' and w == 'a':
        value += .09
    if p == 'so':
        value += {'far': -.64, 'on': -.60, '-called': -.67}.get(w, 0.)
    if p in {'recent', 'early', 'past'} and w in {'years', 'days'}:
        value -= 1.21
    if p == 'right' and w == 'now':
        value -= .52
    if p == 'not' and w in {'yet', 'exist'}:
        value -= .39
    if p in INTENSIFIERS and w in {'common', 'important'}:
        value -= .50 if w == 'common' else .24
    if p == 'well' and w == '-known':
        value -= .60
    if w == 'for':
        value += {'waiting': -.96, 'wait': -.20, 'waited': -.64,
                  'looking': -.35, 'solve': .49, 'solving': .49}.get(p, 0.)
    if w == 'about' and p in {'talk', 'talking', 'talked', 'talks'}:
        value -= .43
    if w == 'on' and p == 'based':
        value -= .22
    if w == 'by' and p in {'provided', 'caused'}:
        value -= .46
    if w == 'in' and p in {'included', 'written', 'distributed', 'located', 'lived'}:
        value -= .24
    if w == 'in' and p in {'covered', 'similar', 'earlier', 'later'}:
        value += .62
    if w == 'in' and p == 'as':
        value -= .31
    if w == 'in' and p == 'described':
        value += .28
    if w in {'in', 'on', 'into', 'of'} and p in {'out', 'off', 'back'}:
        value += .07
    if p in {'in', 'on', 'of', 'to'} and w in {'in', 'on', 'at', 'and'}:
        value += .27
    if w == 'of' and p in {'range', 'period', 'direction'}:
        value += .23
    if w == 'to' and p in {'similar', 'equal'}:
        value += .17
    if w == 'by' and p in {'separated', 'followed'}:
        value += .26
    if w == 'data' and p in {'big', 'large'}:
        value -= .75
    if w == 'team' and p == 'sports':
        value += .31
    if (p, w) in {('linear', 'equations'), ('quadratic', 'equation')}:
        value += .66
    # Punctuation and formatting, including digits after a clock separator.
    if p == ':' and w.isascii() and len(w) == 1 and w.isdigit():
        value += .30 if w == '0' else .14
    if w == ',' and p in {'of', 'to', 'at'}:
        value += .25
    if p == '(' and w == ')':
        value -= .45
    if p == '\":' and w == '"':
        value -= .08
    if w in {'\\t', '\\n'}:
        value -= .10 if w == '\\t' else .04
    if position == 0:
        value += .02
        if w.isdigit():
            value -= .21
        if w.isascii() and w.isalpha():
            value += .03
            if raw[0].isspace():
                value -= .27
            if raw.strip().islower():
                value -= .04
        elif raw.isspace():
            value -= .09
    elif position < 8:
        value += .01
    if position == 1 and p == 'title' and w == ':':
        value = -4.1
    if position == 1 and p == '1' and w == '2':
        value = 2.27
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, previous, position = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = response(previous, word, raw, position)
    return (doc, word, position + 1), float(value)

programs.haiku:
"""Draft 6: a few readable word classes, each read in its local context.

What the component does, as far as a short program can say: its activation is mostly a
lexical, context-dependent signal, and the largest and most consistent parts are these.

1. Partitive "them" ("all of them", "one of them", "most of them") is strongly negative,
   as are "of you / of us / of which / of whom" more weakly.
2. Focus and quantity words right after a preposition or "than" ("in no event", "for just a few",
   "at exactly 2", "to about 5", "than just") are strongly positive. Elsewhere they are near zero.
3. Verbs and participles that need a complement ("known", "shown", "used", "want", "referred",
   "concerned") are negative, most strongly right after an adverb ("widely used", "well known").
4. Small extras: "citizenship" after "of" (country of citizenship) is positive; a run of
   middle dots is positive; the colon in a "Title:" label is negative.
Everything else predicts 0.
"""
READS = ()

PREPOSITIONS = {"in", "for", "to", "of", "than", "with", "under", "by", "at", "on", "from", "about", "into"}
FOCUS_WORDS = {"just", "no", "exactly", "about", "only", "either", "even", "full"}
PARTITIVE_OBJECTS = {"them": -1.4, "you": -0.6, "us": -0.6, "whom": -0.6, "which": -0.5, "it": -0.2}
COMPLEMENT_TAKERS = {"known", "shown", "used", "want", "referred", "concerned", "developed", "created",
                     "await", "welcome", "agree"}
ADVERBS_BEFORE_PARTICIPLE = {"widely", "commonly", "well", "best", "often"}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if w == "··":
        return None, 0.4
    if prev == "of" and w == "citizenship":
        return None, 0.6
    if prev == "of" and w in PARTITIVE_OBJECTS:
        return None, PARTITIVE_OBJECTS[w]
    if w in FOCUS_WORDS:
        return None, 0.8 if prev in PREPOSITIONS else 0.05
    if w in COMPLEMENT_TAKERS:
        return None, -1.2 if prev in ADVERBS_BEFORE_PARTICIPLE else -0.25
    if w == ":" and prev == "Title":
        return None, -1.2
    return None, 0.0

programs.sol:
"""A document-start prior, with special handling for structured text headers.

The largest predictable excursions occur at a document's first token and in
GitHub metadata tags. Initial code declarations, script and capitalization
supply coarse priors; away from the start most predictions stay near zero.
Most word-specific variation is deliberately left unexplained.
"""
import unicodedata
from functools import lru_cache
import regex

READS = ()

SCRIPTS = ('Cyrillic', 'Han', 'Hangul', 'Hiragana', 'Katakana',
           'Arabic', 'Thai', 'Greek')
SCRIPT_PATTERNS = [(name, regex.compile(r'\p{Script=' + name + '}'))
                   for name in SCRIPTS]

# Coarse means for noninitial tokens, not a word or token-id lookup.
BACKGROUND = {'Cyrillic': 0.009, 'Han': 0.001, 'Hangul': -0.013,
              'Hiragana': -0.016, 'Katakana': 0.004, 'Arabic': 0.010,
              'Thai': 0.030, 'Greek': 0.005, 'accented': 0.013}
INITIAL = {'Cyrillic': -0.32, 'Han': 0.04, 'Hangul': 0.60,
           'Hiragana': -0.05, 'Katakana': 0.20, 'Arabic': 0.18,
           'Thai': 0.25, 'Greek': 0.30, 'accented': 0.14}


@lru_cache(maxsize=20000)
def script_of(text):
    for name, pattern in SCRIPT_PATTERNS:
        if pattern.search(text):
            return name
    if any(c.isalpha() and ord(c) > 127 and
           'LATIN' in unicodedata.name(c, '') for c in text):
        return 'accented'
    return 'other'


def initial_value(s):
    word = s.strip()
    indented = s != s.lstrip()
    # Function declarations, data types, and access modifiers are distinct
    # familiar kinds of programming-language keywords.
    if word == 'def':
        return -0.60 if indented else -2.42
    if word == 'int':
        return -1.15 if indented else -1.85
    if word in {'float', 'double', 'char', 'String'}:
        return -0.80
    if word in {'public', 'private', 'protected'}:
        return 0.85 if indented else 1.25
    if word in {'static', 'virtual'}:
        return 0.55 if indented else 0.72
    if word in {'The', 'This', 'That', 'These', 'Those', 'A', 'An'}:
        return -0.18 if indented else -0.40
    if s == '\xa0':
        return -1.34
    if s == ' ':
        return 0.15
    if s == '\t':
        return -0.73
    if s == '\n':
        return -0.03
    if s == '\n\n':
        return -0.19
    if s.isspace():
        return -0.15
    if word == '\\':
        return -0.80
    if word.startswith('#'):
        return -0.25
    if s == '<':
        return -0.329
    if s == ',':
        return 0.18
    if s == '<|endoftext|>':
        return 0.64
    if s.startswith('<|'):
        return -0.08
    kind = script_of(s)
    if kind in INITIAL:
        return INITIAL[kind]
    if word.isalpha():
        if word.isupper() and len(word) > 1:
            return 0.17
        if word.istitle():
            return 0.05 if indented else -0.16
        return 0.0 if indented else -0.035
    return -0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, tail = 0, ''
    else:
        _, n, tail = carry
    s = prefix.token_strings[-1]
    tail = (tail + s)[-80:]
    if n == 0:
        value = initial_value(s)
    elif s == '<think>':
        value = 0.15
    elif s == '</think>':
        value = -0.08
    elif s == '<|im_end|>':
        value = -0.06
    elif s == '<|im_start|>':
        value = -0.04
    else:
        value = BACKGROUND.get(script_of(s), 0.001)
    if n < 32:
        if tail.endswith('<issue_start><issue'):
            value = -1.377
        elif tail.endswith('<issue_start><issue_comment>Title'):
            value = -0.396
        elif tail.endswith('<issue_start><issue_comment>Title:'):
            value = -0.146
        elif tail.endswith('<reponame'):
            value = 1.07
        elif tail.endswith('<gh_stars'):
            value = 1.15 if n == 3 else 0.74
    return (doc, n + 1, tail), float(value)

"""Recognize Romance a/au spellings and French vowel-cluster endings.

The strongest response is to a newly completed eau/eaux or oux, especially
when it is a short word fragment rather than a whole familiar word.  Weaker
responses mark aux, eu/eux, and the preposition a in Spanish or Italian.
Word-frequency dictionaries identify the surrounding language; English's
indefinite article and French's verb a should not get the preposition signal.
Myanmar's independent vowel letter A is a separate strong response.
Only recent same-document text is retained. Other, weak lexical effects
are approximated by zero; this is a spelling heuristic, not a French parser.
"""
import regex as re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LETTERS = re.compile(r"\p{Script=Latin}+")
END_WORD = re.compile(r"\p{Script=Latin}+$")


@lru_cache(maxsize=24000)
def frequencies(word):
    return tuple(zipf_frequency(word.lower(), lang)
                 for lang in ('en', 'fr', 'es', 'it', 'pt'))


def romance_context(text, capitals=False):
    words = LETTERS.findall(text)[-16:]
    if not words:
        return 0.0
    scores = [sum(min(7.0, frequencies(w)[i]) for w in words)
              / len(words) for i in range(5)]
    wanted = max(scores[2], scores[3], scores[1] if capitals else 0)
    other = max(scores[0], scores[4], 0 if capitals else scores[1])
    return min(1.0, max(0.0, (wanted - other + 0.05) / 0.6))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    joined = before + raw
    state = (doc, joined[-800:])
    s = prefix.token_strings[-1]
    token = s.strip()
    low = token.lower()

    if token == 'အ':
        return state, 10.0
    if low in ('à', 'á') and (s != token or s[:1] in "'’"):
        return state, 1.15 if low == 'à' else 0.85
    if low in ("'eau", '’eau'):
        return state, 0.85
    if low in ("'à", '’à'):
        return state, 0.9
    if low == 'a':
        if token == 'A' or s != token or not before[-1:].isalpha():
            value = 1.2 * romance_context(before.decode('utf-8', 'ignore'),
                                          capitals=token == 'A')
        else:
            value = 0.4 if before[-1:].lower() == b'e' else 0.0
        return state, value
    if not any(c in low for c in 'aux'):
        return state, 0.0

    text = joined.decode('utf-8', 'ignore')
    match = END_WORD.search(text)
    word = match.group(0) if match else ''
    w = word.lower()
    capital = float(word[:1].isupper())
    attached = len(word) > len(token) and s == token
    value = 0.0

    if (re.search(r'eau(?:x|[bdfglmprst]{1,2})?$', w)
            and re.search(r'(?:au|u)(?:x|[bdfglmprst]{1,2})?$', low)):
        if w.endswith('eaut'):
            value = 2.0 if attached else 0.35
        elif w.endswith(('eaul', 'eaur', 'eauf', 'eaup', 'eaum', 'eault')):
            value = 4.0
        elif len(token) <= 4:
            common = frequencies(w)[1] > 4.3
            size = len(prefix.token_strings[-2].strip()) if before else 0
            # Familiar endings and long fused prefixes have weaker responses.
            value = (5.4 if size <= 3 else 3.6) if common else 6.8
            if not attached:
                value = 6.5
            elif word.isupper():
                value *= 1.7
        elif attached:
            value = 3.0
        else:
            value = 2.4 if len(word) <= 7 and frequencies(w)[0] > 2.7 else 0.3
    elif w.endswith('yau') and low.endswith('au'):
        value = 5.0
    elif w.endswith('oux') and low.endswith(('oux', 'x')):
        value = 7.0 if low == 'x' else (5.0 if attached else 1.3)
    elif w.endswith('aux') and low.endswith(('aux', 'ux', 'x')):
        short = len(word) == 4 and frequencies(w)[1] < 5.2
        value = (4.2 if short else 1.7) + 1.2 * capital
        if w == 'aux':
            value = 1.6 + 1.0 * capital
    elif w.endswith('au') and low.endswith(('au', 'u')):
        if w == 'au':
            value = 1.2
        elif low == 'u':
            value = 1.7
    elif w.endswith(('eu', 'eux')) and low.endswith(('eu', 'eux', 'ux', 'u', 'x')):
        if w.endswith(('ieu', 'ieux')):
            value = 2.0
        elif attached and w.endswith('eux'):
            value = max(0.0, 3.5 - 0.55 * frequencies(w)[1]) + capital
        elif attached and len(word) > 3:
            value = 0.7
    elif low == 'ume' and w.endswith('aume'):
        value = 1.3
    return state, value

"""Approximate a document-initial pulse, not a topic detector.

Predict zero after the first token of each document. At its first token,
estimate the pulse from source-code opening syntax, English function-word
classes, capitalization, token length, script and ordinary word frequency.
These coarse classes omit token-specific amplitudes and small later responses.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
PREPOSITIONS = set((
    'in on at to of for from with by about into upon over under after '
    'before between through during without within'
).split())
PRONOUNS = set((
    'i we our us my me you your he she it they his her its their them him'
).split())
AUXILIARIES = set((
    'is are was were am be been being do does did have has had can could '
    'will would shall should may might must'
).split())
CONJUNCTIONS = set((
    'and or but as if so than because while although though unless until whether'
).split())
QUANTIFIERS = set((
    'all some any each every both many much few several one other another '
    'such more most less'
).split())
MODULE_DECLARATIONS = set('package using import from namespace'.split())
CODE_STARTERS = set((
    'class const def var int function public private export static void let use'
).split())


def initial_value(s):
    w = s.strip()
    word = w.lower()
    spaced = s[:1].isspace()
    capital = w[:1].isupper()
    title_start = capital and not spaced
    if s == '<|endoftext|>':
        return 11.6
    if s.startswith('<|'):
        return 2.7
    if s.isspace():
        if '\n' in s:
            return 5.1
        return max(3.0, 8.0 - len(s)) if '\t' in s else 2.3
    if not spaced:
        if w in MODULE_DECLARATIONS:
            return 23.5
        if w in CODE_STARTERS:
            return 18.0
        if w.startswith('#!'):
            return 20.5
        if w == '#include':
            return 23.9
        if w.startswith(('#if', '#else', '#endif')):
            return 10.3
        if w.startswith('#'):
            return 20.5 if len(w) < 3 or w[1:].isalpha() else 14.0
        if w == '//' and '\n' in s:  # An empty, completed line comment.
            return -4.0
        if w.startswith(('/*', '//', '"""', "'''")):
            return 19.5
    if w.isascii() and w.isdecimal():
        return -0.4 if int(w) == 0 else 3.0
    if w.startswith('<?'):
        return 10.6
    if word == 'the':
        return (12.2 if spaced else 18.9) if capital else 8.5
    if word in {'a', 'an'}:
        return (10.5 if word == 'a' else 17.0) if capital else 5.5
    if word in PREPOSITIONS:
        if word in {'in', 'on', 'at', 'to'}:
            return 18.7 if title_start else 7.3
        return 12.4 if title_start else 5.7
    if word in PRONOUNS:
        if not title_start:
            return 2.7
        if word in {'we', 'our', 'us'}:
            return 11.0
        if word in {'i', 'my', 'me'}:
            return 8.9
        return 4.2 if word in {'you', 'your'} else 6.6
    if word in AUXILIARIES:
        return 9.0 if title_start else 4.0
    if word in CONJUNCTIONS:
        return 9.0 if title_start else 3.5
    if word in {'this', 'that', 'these', 'those'}:
        return 8.0 if title_start else 3.0
    if word in {'what', 'why', 'who', 'when', 'where', 'how', 'which'}:
        return 7.0 if title_start else 2.3
    if word in QUANTIFIERS:
        return 8.0 if title_start else 3.3
    if w.isascii() and w.isalpha():
        if title_start:
            return 11.0 if len(w) <= 2 else 6.0 if len(w) == 3 else 3.5
        frequency = zipf_frequency(w, 'en')
        if spaced:
            return (2.3 if frequency >= 6 else 1.3) + (1.5 if capital else 0)
        return 2.8 if frequency >= 2 else 1.7
    if regex.fullmatch(r'\p{Script=Cyrillic}+', w):
        return 11.5 if title_start else 3.0
    if regex.search(r'\p{Script=Han}', w):
        return 0.5
    if len(w) == 1 and w.isascii():
        if w in ':?!)]}':
            return 0.8
        if w == '<':
            return 16.0
        return 6.5 if w in '([{;>"' else 3.0
    return 1.5


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    value = initial_value(prefix.token_strings[-1]) if first else 0.0
    return document, value

