"""Candidate 4: the first token of each document, valued by what kind of opening it is."""
READS = ()

# Tokens that open a source file or a code line (exact, no leading space).
CODE_OPENERS = {"package", "import", "using", "from", "const", "def", "class", "function",
                "var", "int", "#include", "#define", "#", "##", "//", "/*", "#!/"}
# Words that open an English sentence or title.
SENTENCE_OPENERS = {"The", "In", "On", "To", "An", "With", "For", "This", "By", "As", "We"}


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids
    if t > 0 and doc[t] == doc[t - 1]:
        return carry, 0.0  # inside a document: the component is silent
    s = prefix.token_strings[t]  # the document's first token
    w = s.strip()
    if s in CODE_OPENERS:
        value = 20.0
    elif w in SENTENCE_OPENERS:
        value = 16.0
    elif len(w) == 1 and w.isupper():
        value = 10.0  # a lone capital letter
    elif w[:1].isupper():
        value = 8.0  # a capitalised word
    elif s[:1] == " ":
        value = 4.0  # a word with its leading space
    elif s[:1].islower():
        value = 3.5
    elif s[:1].isdigit():
        value = 2.5
    elif s[:1].isascii():
        value = 6.0  # punctuation and symbols
    else:
        value = 1.0  # CJK and other scripts: near zero
    return carry, value

programs.sol:
"""Surface-pattern approximation of a number/negation continuation feature.

Positive pulses occur at labelled numbers, expressions in n, and 'not only'
(in several languages). Negative pulses occur inside unfinished n/ne-initial
words, particularly Cyrillic не- and Slavic nie-/ně-. These are spelling
rules, not a claim that all such words mean negation. A document-initial
'Title:' metadata label has its own pulse; everything else is zero.
"""
import re

READS = ()
NUMBER_WORDS = set('one two three four five six seven eight nine ten'.split())
NOT_ONLY = {
    'not': 'only', 'не': 'только', 'nie': 'tylko',
    'nicht': 'nur', 'non': 'solo', 'no': 'solo',
}
LABEL = re.compile(r'(?<![A-Za-z])(?:[Nn][Oo]\.|[Nn]\.|Nr\.|[Nn]°)$')
HASH = re.compile(r'(?:^|[\s(])#\s*$')
FORMULA = re.compile(r'(?<![\w])[nN]\s*(?:==?|[+\-−/<>]|//)\s*$')
N_ALONE = re.compile(r'(?<![\w])[nN]$')
WORD = re.compile(r'([^\W\d_]+)$')


def activation(before, token):
    s = token.strip()
    match = WORD.search(before)
    word = match[1].lower() if match else ''
    if before == 'Title' and token == ':':
        return 14.25
    if not before and token == 'Title':
        return -1.38
    if NOT_ONLY.get(word) == s:
        return 6.3
    if word == 'number':
        if s == 'one':
            return 8.5
        if s in NUMBER_WORDS or s.isdigit():
            return 3.0
        if token == ' ':
            return 2.9
    if LABEL.search(before.rstrip()):
        if token == ' ':
            return 5.2
        if s.isdigit():
            return 3.0
    if word == 'no' and token == '.':
        return 1.5
    if N_ALONE.search(before) and token in ('°', '.', '=', ' ='):
        return 0.8
    if FORMULA.search(before):
        if s.isdigit():
            return 2.3
        if token == ' ':
            return 1.3
    if s.isdigit() and HASH.search(before):
        return 2.5
    # No space: the token continues the same unfinished word.
    if token[:1].isalpha():
        if word == 'н' and s.lower().startswith('е'):
            return -2.5
        if word == 'n' and s.lower().startswith(('e', 'ie')):
            return -0.6
        if word.startswith('не') and len(word) <= 3:
            return -4.6
        if word.startswith(('nie', 'ně')) and len(word) <= 4:
            return -3.0
        if re.fullmatch(r'ne[^aeiouwt]?', word):
            # Exclude the unrelated new-/net-/neo-/neu- spelling families.
            if not (word + s.lower()).startswith(('new', 'net', 'neo', 'neu')):
                return -1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(before, token)
    return (doc, (before + token)[-80:]), value

programs.haiku:
"""Layer-1 MLP unit 1567. Plain-terms summary of what it responds to:

  * "only" right after a negation: "not only", "не только", "nicht nur",
    "non solo", "nie tylko" -> about +6.5. Any other "only" is slightly negative (-0.3).
  * the number that follows a reference label, as in "No. 47", "Nr. 3", "Nº 5", "n = 5",
    "#1", "number one":
      space after "No." / "Nr." / "n."          +4
          (+8 when the label follows "the", "world", "at", as in "the No. 1")
      digit after "No." / "Nr."                 +3.1
      space or digit after "number"             +4   ("number one" +7.5)
      space after "n ="                         +1.8 ; digit after "n ="  +3.7
      digit after "#"                           +3
      "No" followed by "."                      +1.5
      "n" followed by " =" +2.5 (or "=" alone +0.7)
      "Title:" label                            +3 (noisy)
  * the piece right after a bare negation prefix at the start of a word, which is split
    off by the tokenizer: Russian "неп|рав", "нед|ост", "нез|аб" -> about -6.5;
    Polish "naj|", "nie|", "nied|" -> -4.5 to -6.5; Russian "не|" -> -2.4;
    Czech/English "ne|" -> -1.
    A lone Russian "н" followed by "ез"/"еп"/"еб" gets 0.7 of the matching value.
  * the dot-leader token "··" -> -0.5.

Everything else is 0. Activations are sparse: nearly all their variance is in these spikes.
"""

READS = ()

NEGATIONS = {"not", "не", "nicht", "non", "no", "nie", "ne", "nein"}
ONLY_WORDS = {"only", "только", "nur", "solo", "sólo", "tylko", "solamente"}
RANK_WORDS = {"the", "a", "world", "in", "at", "ranked", "to", "as"}
LABELS = ("no", "nr", "nos", "n")  # labels abbreviating "number", written with a period
NEG_PREFIX = {  # bare negation prefix -> predicted value of the piece after it
    "неп": -6.6, "нед": -6.8, "нез": -7.3, "нел": -6.9, "нев": -3.5, "нер": -6.0,
    "nie": -4.5, "nied": -6.5, "nej": -7.9, "naj": -6.1, "niew": -6.0,
    "не": -2.4, "ne": -1.0,
}


def _clean(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    cur = strs[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        before, word = [], ""
    else:
        before = [_clean(s) for s in strs[-5:-1] if s.strip()]
        word = carry or ""

    # The word so far (lower case). A token with a leading space starts a new word.
    piece = _clean(cur)
    if cur[:1].isspace() or not piece.isalpha():
        word_before, word_now = "", (piece if piece.isalpha() else "")
    else:
        word_before, word_now = word, word + piece
    new_carry = word_now

    blank = cur.strip() == ""
    digit = piece.isdigit()
    last = before[-1] if before else ""
    last2 = before[-2:]

    # negation prefixes inside words
    if word_before in NEG_PREFIX:
        return new_carry, NEG_PREFIX[word_before]
    if word_before == "н" and word_now in NEG_PREFIX:
        return new_carry, 0.7 * NEG_PREFIX[word_now]
    # "only" after a negation, and ordinary "only"
    if piece in ONLY_WORDS and last in NEGATIONS:
        return new_carry, 6.5
    if piece in ONLY_WORDS:
        return new_carry, -0.3
    if piece == "··":
        return new_carry, -0.5
    # reference numbers
    if last == "." and len(last2) == 2 and last2[0] in LABELS:
        if blank:
            ranked = len(before) >= 3 and before[-3] in RANK_WORDS
            return new_carry, 8.0 if ranked else 4.0
        if digit:
            return new_carry, 3.1
    if last == "n" and piece == "=":
        return new_carry, 2.5 if cur[:1].isspace() else 0.7
    if last == "=" and len(last2) == 2 and last2[0] == "n":
        if blank:
            return new_carry, 1.8
        if digit:
            return new_carry, 3.7
    if last == "°" and digit and len(last2) == 2 and last2[0] == "n":
        return new_carry, 3.5
    if piece == "°" and last == "n":
        return new_carry, 3.0
    if last == "#" and digit:
        return new_carry, 3.0
    if last == "number" and piece == "one":
        return new_carry, 7.5
    if last == "number" and piece in ("two", "three", "four", "five"):
        return new_carry, 4.5
    if last == "number" and (blank or digit):
        return new_carry, 4.0
    if last == "no" and piece == ".":
        return new_carry, 1.5
    if last == "title" and piece == ":":
        return new_carry, 3.0
    return new_carry, 0.0

programs.sol:
"""A German spelling contrast, carried across the pieces of each word.

Recent words' dictionary frequencies estimate whether the text is German.
Within German text, lowercase word pieces usually have a positive response;
capitals away from sentence beginnings have a negative one. Prefixes spelling
very frequent German words are weak. A word keeps its initial case across
tokenizer pieces. Non-Latin words receive zero; document boundaries reset state.
The amplitude corrections use frequency, word position, and token length,
not token identities. This does not reproduce individual lexical exceptions.
"""
import regex as re
import codecs
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('de', 'en', 'nl', 'fr', 'es', 'it', 'sv', 'pl')


@lru_cache(maxsize=100000)
def frequencies(word):
    return tuple(zipf_frequency(word.lower(), lang) for lang in LANGUAGES)


def clip(x, low=0., high=1.):
    return max(low, min(high, x))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0., True, True, b'')
    _, word, language_score, next_sentence, word_sentence, pending = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]

    chunks = re.findall(r'[^\W\d_]+|[\W\d_]+', text)
    for chunk in chunks:
        if chunk.isalpha():
            if not word:
                word_sentence = next_sentence
                next_sentence = False
            word += chunk
        else:
            if word:
                fs = frequencies(word)
                if max(fs) >= 3:
                    evidence = clip(fs[0] - max(fs[1:]), -2., 2.)
                    language_score = .82 * language_score + .18 * evidence
            word = ''
            if any(c in chunk for c in '.!?\n'):
                next_sentence = True

    carry = (doc, word, language_score, next_sentence, word_sentence, pending)
    if not word or not re.fullmatch(r'\p{Latin}+', word):
        return carry, 0.
    fragments = re.findall(r'[^\W\d_]+', text)
    fragment = fragments[-1] if fragments else ''
    fs = frequencies(word)
    german_frequency = fs[0]
    german = clip((language_score - .1) / .6)
    common_word = clip((6.7 - german_frequency) / .7)
    prior_letters = max(0, len(word) - len(fragment))
    # Coefficients below are fitted on training text only.
    if word[0].isupper():
        amplitude = -1.21 + 1.00 * word_sentence
    else:
        amplitude = (1.42 + 1.17 / (1 + prior_letters)
                     - .71 * clip(german_frequency - 4., 0., 2.5)
                     - .156 * min(len(fragment), 8))
    return carry, float(german * common_word * amplitude)

"""Approximate strong line-wrap and document-opening responses.

Long lines ending in English function words receive larger break predictions.
Backslashes are stronger in prose-like context; an ensuing n token inherits
most of their estimate. Blank lines are weaker. Two additional triggers are
Title: headers and PHP opening tags at the start of a document.
Other positions are generally assigned zero; this is only a partial account.
"""
READS = ()

UNFINISHED = set('''a an the of in on at to for with by from and or but as if
that which who whose this these those is are was were be been being have has had
do does did will would could should may might must not no it its he his she her
they their we our you your'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', (), 0.0, 0, 0)
    _, previous, history, escape, line_length, position = carry
    text = prefix.token_strings[-1]
    word = previous.strip()
    function = word.lower() in UNFINISHED
    letters = bool(word) and word[-1].islower()
    spaced = previous.startswith(' ')
    prose = sum(h[0] for h in history) >= 8
    value = 0.0
    next_escape = 0.0

    if text and not text.strip() and '\n' in text:
        if spaced and function:
            if line_length >= 50:
                value = 0.44
            elif line_length >= 28:
                value = 0.13
            else:
                value = 0.04
        elif letters and line_length >= 60 and not any(h[1] for h in history):
            value = 0.10 if spaced else 0.04
        if text.count('\n') > 1:
            value *= 0.3
        if '\r' in text and letters and line_length >= 34:
            value = 0.40
    elif text in ('\\', ' \\', '\\n'):
        if spaced and function:
            value = 0.85 if prose else 0.42
        elif spaced and letters:
            value = 0.70 if prose else 0.15
        elif letters:
            value = 0.08
        elif previous.endswith(',') and prose:
            value = 0.30
        if text in ('\\', ' \\'):
            next_escape = value
    elif previous.endswith('\\') and text.startswith('n'):
        value = 0.85 * escape
    elif text == '-\n' and letters:
        value = 0.40

    # Two document-opening formats also give strong, reproducible responses.
    if position == 0:
        if text == 'Title':
            value = 0.32
        elif text == '<?':
            value = 0.21
    elif position == 1:
        if previous == 'Title' and text == ':':
            value = 2.88
        elif previous == '<?' and text == 'php':
            value = 1.43

    word_token = text.startswith(' ') and text.strip().isalpha()
    code_token = any(c in text for c in '{};_=<>')
    history = (history + ((word_token, code_token),))[-12:]
    line_length = 0 if '\n' in text else line_length + len(text)
    return (doc, text, history, next_escape, line_length, position + 1), value

"""Recognize the beginning of a signed value or a parenthesized expression.

A minus sign is strong after an equality, comparison, comma, or words that
introduce a value.  It is quiet in subtraction, hyphenated words and bullets.
Opening parentheses and brackets give smaller responses in the same settings;
coordinate-introducing words especially favor parentheses.  Fused punctuation
such as '(-' gets a separate, moderate response. A final 0.8 gain
keeps these approximate predictions conservative.
"""
import re

READS = ()
MATH = re.compile(r'[0-9=<>±≈≤≥^]|\b(?:point|coordinates|vector|matrix|x|y|z)\b')

COPULAS = {
    'is', 'are', 'was', 'were', 'be', 'being', 'been',
    'equals', 'equal', 'becomes',
}
APPROXIMATION = {'approximately', 'about', 'approaches', 'approaching'}
VALUE_VERBS = {'return', 'compute', 'suppose', 'gives', 'yields', 'gave', 'got'}
COORDINATES = {'point', 'points', 'pair', 'pairs', 'vector', 'coordinates'}


def introduction(previous, recent):
    """Strengths of a signed value and an opening parenthesis, respectively."""
    p = previous.strip()
    w = p.lower()
    word = re.search(r'[^\W\d_]+$', recent)
    if word and p and p[-1].isalpha():
        w = word[0].lower()
    if not p or previous.endswith('\n'):
        return 0.0, 0.0
    if p.endswith('≈'):
        return 9.2, 1.8
    if p[-1] in '=<>≤≥≠≡→⇒∈' or w in {'rightarrow', 'to'}:
        return 7.1, 1.4
    if p[-1] in ',:':
        return 5.7, 0.9
    if p[-1] in '([{':
        return 4.9, 1.05
    if p[-1] in '+-−':
        return 2.8, 0.75
    if p[-1] in '*/÷×^':
        return 1.7, 0.8
    if p in {'~', '$', '$$'} and previous.startswith(' '):
        return 6.8, 0.6
    if p == '@@':  # the old line range at the start of a patch hunk
        return 4.0, 0.0
    if w in COPULAS:
        return 6.3, 1.8
    if w in APPROXIMATION:
        return 7.8, 2.6
    if w in {'between', 'from', 'than'}:
        return 7.5, 2.1
    if w == 'at':
        return 6.0, 3.3
    if w in {'of', 'as', 'by', 'and', 'or', 'into'}:
        return 5.4, 1.1 if w != 'or' else 0.3
    if w in VALUE_VERBS:
        return 4.5, 0.8
    if w in COORDINATES:
        return 1.0, 1.8
    if w in {'in', 'with', 'that', 'the'}:
        return 2.0, 0.6
    return 0.0, 0.0


def activation(token, previous, recent):
    t = token.strip()
    if not t or (t[0] not in '-−–±+([{|.~' and t != 'negative'):
        return 0.0
    sign, opening = introduction(previous, recent)
    mathematical = bool(MATH.search(recent))
    if previous.strip() == ',':
        sign = 6.5 if re.search(r'\d\s*,$', recent) else 3.6
        if not mathematical:
            sign *= 0.4
    if t == '−':
        sign *= 0.8
    if previous.strip().lower() in {'at', 'from'} and not mathematical:
        opening *= 0.4
    spaced = token.startswith(' ')
    if '\n' in token:
        return 0.0
    if t == '–' and not mathematical:
        return -0.1
    if t in {'-', '−', '–'}:
        if not previous:
            value = 0.0 if spaced else -1.0
        elif spaced:
            value = sign if sign else 0.15
        else:
            p = previous.strip()
            value = sign if p and p[-1] in '=<>≤≥≈≠([{→⇒' else 0.0
            if p.endswith('='):
                value *= 0.8
            if previous.startswith(' ') and p in {'$', '$$'}:
                value = 6.0
            if p == '&':
                value = 5.4
            if previous == '\xa0':
                value = 1.6
            if previous.endswith('\n\n'):
                value = 1.3
        return value
    if t and t.count('-') == 1 and t.endswith('-') and len(t) > 1:
        head = t[:-1]
        if all(c in '([{=,|' for c in head):
            value = 2.8 if '(' in head or '[' in head else 3.4
            if '[' in head and not mathematical:
                value *= 0.4
            return value
    if t in {'-(', '-\\', '-.'}:
        return sign * 0.6 + (0.5 if mathematical else 0.0)
    if t == '±':
        return min(8.7, 1.2 * sign) if sign else -0.15
    if t == '+':
        return 0.58 * sign - 0.12
    if t == '(':
        return opening if spaced else (0.6 if sign > 0 else 0.02)
    if t == '[':
        return min(1.2, opening * 0.55) if spaced else 0.0
    if t == '|':
        return sign * 0.4 if mathematical else 0.0
