ASK_VERBS = {"help", "show", "give", "tell", "provide", "send"}
MODALS = {"can", "could", "would", "will"}
ABILITY = {"easily", "possibly", "you", "please", "explain", "anyone"}
QUANTIFIERS = {"any", "every", "all", "no"}
POSSIBLE = {"possible", "possibly"}
