import unicodedata

READS = ()


def start_value(s):
    word = s.strip()
    if s == '//\n':  # An empty line comment opening a source file.
        return -6.05
    if s.startswith(' ') and word.istitle() and word.isascii():
        return -0.75
    if s.isascii() and s.isalpha() and s.isupper():
        return 0.33
    if len(word) == 1 and word.isascii() and word.isalpha():
        return -0.39
    if s and all(unicodedata.category(c).startswith('P') for c in s):
        return 0.19
    return -0.18


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, tail, pos = '', '', 0
    else:
        _, prev, tail, pos = carry
        pos += 1
    newline = tail.endswith('\n')
    escaped = tail.endswith('\\n')
    value = 0.0
    if pos == 0:
        value = start_value(s)
    elif s == ' ':
        if newline:
            value = 1.2 + 1.5 / (1.0 + pos / 12.0)
        elif escaped:
            value = 1.95
        elif prev.endswith(('\"', "'", '`')):
            value = 0.94
        elif prev.isspace():
            value = 0.20 if len(prev) == 4 else -0.05
    elif s and not s.strip(' \t'):
        spaces = len(s) - len(s.rstrip(' '))
        if spaces % 4 == 1:
            if newline:
                value = 0.63
            elif escaped:
                value = 0.81
            elif s.startswith('\t') and spaces >= 5:
                value = 0.44
            else:
                value = 0.10
        elif newline and spaces == 4:
            value = -0.11
        elif newline and spaces == 2:
            value = -0.04
        elif spaces >= 7 and spaces % 4 == 3:
            value = -0.06
    elif s == '\xa0':
        if prev.endswith('`'):
            value = 0.9
        elif prev == '\xa0':
            value = 0.65
        else:
            value = 0.32 if prev.isspace() else 0.02
    elif s == '``':
        value = 0.7 if prev.endswith('\xa0') else 0.13
    elif len(s) >= 2 and not s.strip('\\'):
        value = min(1.5, 0.15 + 0.4 * (len(s) - 2))
    return (doc, s, (tail + s)[-2:], pos), value

