            return 2.0
        if token.isdecimal() and re.search(group + '-[0-9]$', combined):
            return 2.4
        if token == '-' and re.search(r'ISBN[\s:]*97[89]-$', combined):
            return 0.8
        if token == '9' and re.search(r'ISBN[\s:]*9$', combined):
            return 0.7
        if token == '-' and re.search(r'ISBN[\s:]*[0-9-]+-$', combined):
