    r'(年|月|日|天|周|週|星期|上午|下午|晚上|早上|平时|平時|'
    r'以前|以后|以後|之前|之后|之後|目前|当前|當前|现在|現在|'
    r'这次|這次|此次|本次|本期|这期|這期|一期|当天|當天|'
    r'今年|去年|明年|今天|昨天|明天|最后|最後|最新|刚才|剛才|'
    r'月末|周末|年末|年底|年前|年后|年後|天前|天后|天後)$')

def numeric_field(left, separator, right, digit):
    """A new field is stronger after a larger, longer number; then it fades."""
    scale = min(len(left), 4) - 1
