        if word in {'instance', 'instances'}:
            return 1.4
        if word in {'edition', 'editions', 'episode', 'episodes', 'issue'}:
            dated = bool(re.search(r'[0-9]{4} (issue|edition|editions)$', text)) or any(
                w.lower() in MONTHS for w in re.findall(r'[A-Za-z]+', text[-50:]))
            return (-6.0 if word in {'issue', 'edition', 'editions'} else -2.8) if dated else -1.5
    if s == 'in':
        if word == 'published':
            return -1.75
        if word == 'time' and before_word.endswith('first'):
            return 2.8
    if s == 'to':
        if word in TIME_UNITS or word in MONTHS:
            return 1.1
        if text and text[-1] in DIGITS:
            return .4
    if token == '的' and CHINESE_TIME.search(text):
        return -5.5 if re.search(r'(当天|當天|今年|每年|下午|本期|月末)$', text) else -3.2
    if token == 'の' and re.search(r'(年|月|日|時|今日|昨日|現在|今回|以前|今年)$', text):
        return -2.1
    if s in {'issue', 'edition', 'editions', 'episode', 'episodes'}:
        if re.search(r'[0-9]{4}$', text):
            return -5.5 if s in {'issue', 'edition', 'editions'} else -2.0
        return -1.0 if s != 'issue' else 0.0
    if s in {'today', 'tonight', 'yesterday', 'tomorrow'}:
        return -.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else b''
    text = history.decode('utf-8', errors='replace')
    token = prefix.token_strings[-1]
    value = predict(text, token)
    return (doc, (history + prefix.token_bytes[-1])[-360:]), value

"""Approximate a sparse, signed spelling feature.

Flood-related spellings across several scripts are strongly negative.
Selected f-continuations are positive: -ang/-ong, -ur, and number-word
pieces.  Selected split fl- spellings are negative.  Other lexical
responses are deliberately omitted.  UTF-8 characters are assembled
across tokens, state resets at document boundaries, and document starts
receive a small bias.
"""
import codecs
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    decoder = (codecs.getincrementaldecoder('utf-8')('replace')
               if first else carry[2])
    split_character = bool(decoder.getstate()[0])
    text = decoder.decode(prefix.token_bytes[-1])
    s = text.lstrip().lower()
    continues = not text[:1].isspace()
    previous = previous if continues else ''
    joined = previous.lower() + s
    value = -0.37 if first else 0.0
    if first and s == '<|im_start|>':
        value = 0.49

    # Fire when the spelling first becomes identifiable, not on every suffix.
    if 'flood' in joined and 'flood' not in previous.lower():
        value = -4.8 if s == 'flooded' else -7.5
        if not s.startswith('flood'):
            value = -9.5
    elif previous.lower().endswith('flood') and s.startswith('water'):
        value = -4.0
    elif s in ('fled', 'flee', 'fleeing'):
        value = -1.8
    elif s == 'erosion' and not first and carry[1].lower() == 'soil':
        value = -1.5
    elif s == 'fang':
        value = 0.8
    elif s in ('fur', 'fa'):
        value = 0.5

    # Flood/disaster morphemes and related syllables.
    if s in ('洪', '洪水'):
        value = -10.0 if split_character else -6.3
    elif s == '홍':  # Korean hong, also used in the word for flood.
        value = -3.8
    elif s == '灾':
        value = -4.5
    elif s in ('災', '灾害', '災害'):
        value = -4.0 if split_character else -2.8
    elif s == '水' and previous.endswith('洪'):
        value = -3.5
    elif s == '害' and previous.endswith(('灾', '災')):
        value = -2.8
    elif s in ('滥', '濫'):
        value = -3.0
    elif s in ('泛', '祸', '禍'):
        value = -2.8 if split_character else -1.1
    elif s == 'ũ' and previous.lower().endswith('l'):
        value = -6.5  # Vietnamese lũ, flood; also appears inside longer words.

    if not text[:1].isspace() and previous.lower().endswith('f'):
        if s in ('ang', 'angs', 'ong'):
            value = 4.3
        elif s.startswith(('äng', 'imm')):
            value = 3.0
        elif s == 'ours':
            value = 4.5
        elif s in ('one', 'our', 'iv', 'ive', 'ives'):
            value = 3.2
        elif s in ('ur', 'urring'):
            value = 2.6
        elif s.startswith('lood'):
            value = -10.0
        elif s.startswith(('lee', 'led')):
            value = -4.2
        elif s.startswith('l'):
            value = -1.5
        elif s.startswith(('ro', 'idd', 'ood', 'ung', 'um')):
            value = -0.9
        elif s.startswith(('ath', 'ooth')):
            value = -2.8
        elif s == 'error' and previous.lower().endswith('if'):
            value = 2.0
        elif s.startswith('ag'):
            value = 0.8
    elif continues and previous.lower().endswith('fl'):
        if s.startswith('uth'):
            value = -7.0  # German Fluth, the older spelling of Flut (flood).
        elif s.startswith('ut'):
            value = -3.5
        elif s.startswith(('u', 'ü')):
            value = -2.5

    # Only a trailing word fragment is needed at the next token.
    tail = re.search(r'[^\W\d_]+$', joined)
    return (doc, tail.group()[-24:] if tail else '', decoder), value

programs.haiku:
"""Candidate 5: arrows that link a name to a fact, and forum-profile labels.

The component is negative on arrows. Strongest (about -2) on a '->' that follows a bare name
at the start of a line: the subject of a 'Name -> property -> value' fact list (for example
'monica (actress) -> occupation -> ...'). Weaker (about -0.3) on other arrows ('->', '-->',
'→', '=>', '⇒'), which mostly appear in code and maths. Also negative: a '›' page separator,
and the colon after a forum-signature label ('Joined:' strongest, 'Forum:' and 'Posts:' weaker)."""
READS = ()

OTHER_ARROWS = {"->", "-->", "→", "=>", "⇒"}
LABEL_STRENGTH = {"Joined": -1.5, "Forum": -1.0, "Posts": -0.4}

def _line_before(prefix, limit=8):
    """Tokens between the start of the current line and the current token."""
    out = []
    for i in range(len(prefix) - 2, -1, -1):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        s = prefix.token_strings[i]
        if "\n" in s or s == "<|endoftext|>":
            break
        out.append(s)
        if len(out) == limit:
            break
    return out[::-1]

def _is_name(words):
    """Only letters, spaces and parentheses, with at least one letter."""
    text = "".join(words)
    letters = [c for c in text if c.isalpha()]
    return bool(letters) and all(c.isalpha() or c in " ()'.-" for c in text)

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok == "->":
        return None, (-2.0 if _is_name(_line_before(prefix)) else -0.3)
    if tok in OTHER_ARROWS:
        return None, -0.3
    if tok == "›" and len(prefix) > 1:
        return None, -2.0
    if tok == ":" and len(prefix) > 1:
        return None, LABEL_STRENGTH.get(prefix.token_strings[-2].strip(), 0.0)
    return None, 0.0

programs.sol:
"""A heuristic detector of grammatical endings in agglutinative languages.

Japanese manner/adjective endings, case particles, limits and counters tend
negative, as do Hungarian case endings and Korean adverbial endings. Bare
suffix tokens often have a stronger response than endings inside larger
pieces. Dictionary translations help distinguish Japanese adjective -ku
from verbs. Certain Korean future-attributive endings instead get a
positive value, as does a title-field colon at the start of a document. This is a heuristic, not a morphological parser.

Keep a short byte buffer for word/language context and split UTF-8 letters;
reset it at document boundaries. Also recognize a document-opening Title:.
"""
import re
from functools import lru_cache
import regex
import jmdict
import wordnet

READS = ()
LATIN = regex.compile(r'\p{Latin}+')
JP_END = regex.compile(r'[\p{Script=Han}\p{Script=Hiragana}]+$')
HU_CUES = set('hogy és egy nem vagy az ezt ezek aki mert kell már csak '
              'mint után amely akkor még lehet pedig'.split())
ADVERBS = set('すぐ すぐに 常に 必ず ゆっくり しっかり たっぷり '
               'どんどん ますます さっそく 早速 若干 色々 様々 '
               'いろいろ 一番 いっぱい'.split())
DEGREE = set('だけ ほど くらい ぐらい 程度 しか ばかり 限り '
             '多数 いくつか ある程度'.split())
COUNTERS = set('個 件 枚 回 分 倍 本 人 度'.split())


@lru_cache(maxsize=12000)
def adjective_ku(word):
    """Compare dictionary adjective and verb readings of the word's end."""
    adjective_span = verb_span = 0
    for n in range(2, min(9, len(word) + 1)):
        ending = word[-n:]
        if any(g.startswith('to ') for g in jmdict.glosses(ending)):
            verb_span = n
        for gloss in jmdict.glosses(ending[:-1] + 'い'):
            if 'adjective' in wordnet.parts_of_speech(gloss.split(' (')[0]):
                adjective_span = n
                break
    return adjective_span > verb_span


def japanese(s, text):
    v = 0.0
    if s.endswith('く'):
        m = JP_END.search(text)
        word = m.group() if m else s
        adjective = False
        if s.endswith('しく'):
            v = -5.39
        elif s in ('よく', '良く'):
            v = -4.04
        elif s.endswith(('なく', '無く')):
            v = -2.22
        elif s == '全く':
            v = 1.35
        elif word.endswith(('っぽく', 'にくく', 'たく')) or adjective_ku(word):
            v, adjective = -2.31, True
        else:
            v = 0.10
        if s == 'く':
            v -= 1.67 + (1.96 if adjective else 0.0)
    elif s in ADVERBS:
        v = -2.37
    elif s in ('まで', '迄'):
        v = -4.72
    elif s.endswith('ように'):
        v = -3.28
    elif s.endswith('的に'):
        v = -2.76
    elif s in DEGREE:
        v = -2.10
    elif s == 'で':
        v = -1.17
    elif s == 'に':
        v = -0.63
    elif s == 'へ':
        v = -2.17
    elif s.endswith('に') and len(s) > 1:
        v = -0.71
    elif s in ('でも', 'ため', 'として', 'によって', 'だけで', 'たり', 'ったり'):
        v = -0.68
    elif s in ('を', 'が', 'は'):
        v = 0.11
    if s == 'つ' and re.search(
        r'[0-9０-９一二三四五六七八九十]つ$|いくつ$|ずつ$|つつ$', text
    ):
        v -= 2.70
    elif s in COUNTERS and re.search(
        r'[0-9０-９一二三四五六七八九十何]' + re.escape(s) + r'$', text
    ):
        v -= 0.92
    if s in ('以上', '以下', '以内', '以外', '以上の'):
        if regex.search(r'\p{Script=Hiragana}', text[-150:]):
            v -= 2.18  # Distinguish Japanese usage from Chinese usage.
    if s == '々':
        v -= 1.71
    return v


def hungarian(s, token, text):
    words = LATIN.findall(text[-400:].lower())
    if not (re.search('[őű]', text[-400:]) or len(set(words) & HU_CUES) >= 2):
        return 0.0
    w, v = words[-1], -0.17
    bound = not token[:1].isspace()
    instrumental = w.endswith(('val', 'vel')) or re.search(
        r'([bcdfghjklmnpqrstvwxyz])\1[ae]l$', w
    )
    if instrumental:
        v -= 1.73 + (4.69 if bound else 0.0)
    elif w.endswith(('ból', 'ből', 'tól', 'től', 'ról', 'ről')):
        v -= 5.57
    elif w.endswith(('ban', 'ben', 'on', 'en', 'ön', 'án', 'én', 'nál', 'nél')):
        v -= 1.94
    elif w.endswith(('ra', 're', 'ba', 'be', 'hoz', 'hez', 'höz')):
        v -= 1.39
    elif w.endswith(('an', 'ul', 'ül', 'lag', 'leg', 'ként')):
        v -= 1.95
    elif w.endswith(('kat', 'ket', 'it', 'ait', 'eit')):
        v -= 2.95
    elif w.endswith(('nak', 'nek', 'ért', 'ig', 'kor')):
        v -= 0.89
    if bound:
        if s in ('ban', 'ben', 'án', 'én', 'on', 'en', 'ön', 'ra', 're', 'an'):
            v -= 3.26
        if s in ('at', 'et', 'ot', 'öt', 't', 'át', 'ét'):
            v -= 1.08
        if s == 'ig':
            v -= 3.90
    elif s in ('is', 'igen'):
        v -= 2.78
    elif s in ('a', 'az'):
        v += 0.68
    return v


def korean(s, text):
    if s.endswith('로'):
        return -2.51
    if s.endswith('게'):
        return -1.44
    if s in ('까지', '씩', '도록', '하도록', '있도록'):
        return -2.76
    if s in ('함께', '없이'):
        return -1.83
    if s == '을' and re.search(r'[었았였없있]을$', text):
        return 5.98  # Future attributive after past or existential stems.
    if s in ('은', '는', '을', '를'):
        return 0.51
    if s in ('에', '부터', '고', '이'):
        return -0.32
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, position = (b'', 0) if carry is None or carry[0] != doc else carry[1:]
    data = old + prefix.token_bytes[-1]
    text = data.decode('utf-8', 'ignore')
    token = text[len(old.decode('utf-8', 'ignore')):]
    s = token.strip()
    value = 0.003 + japanese(s, text) + korean(s, text)
    if LATIN.fullmatch(s):
        value += hungarian(s, token, text)
    if position == 1 and s == ':' and text.endswith('Title:'):
        value = 11.30
    return (doc, data[-1600:], position + 1), float(value)

"""A boundary/typography approximation of this component.

Message endings have a large negative value, especially after a completed
sentence; tool endings are weaker. Other rules recognize spaced punctuation,
blank-line artifacts, invisible characters and incomplete UTF-8 letters.
Attribution headers ("Posted by", "Written by", etc.) give a positive value.
Ordinary words are left at zero, apart from a small document-start signal.
"""
import re
import unicodedata
import regex

READS = ()
MARKERS = {
    '<|im_start|>': 0.096,
    '<think>': 0.107,
    '</think>': -0.48,
    '<tool_response>': 0.37,
    '</tool_response>': 0.10,
}
CREDIT_VERBS = frozenset('''
    asked posted written created reviewed published modified developed uploaded
    referenced contributed converted designed edited sponsored directed started
    presented decompiled
'''.split())


def ending_value(previous):
    if previous == '</tool_call>':
        return -0.17
    if previous == '</tool_response>':
        return -0.60
    ending = previous.rstrip()
    if ending.endswith('。'):
        return -2.36
    if ending.endswith('.'):
        return -2.15
    return -1.36 if ending[-1:].isalnum() else -1.89


def typography(text, raw, previous):
    if text in MARKERS:
        return MARKERS[text]
    if text == '<|im_end|>':
        return ending_value(previous)
    if text == '··':
        return 1.37
    if text == ' …':
        return 0.44
    if text == ' ·':
        return -0.30
    stripped = text.strip()
    if stripped and all(unicodedata.category(c) == 'Cf' for c in stripped):
        return -2.2 if '\u200e' in text else -0.35
    if stripped in ('ˈ', 'ˌ'):
        return -0.6
    if regex.fullmatch(r'\p{Block=IPA_Extensions}+', stripped):
        return -0.4
    if text.isspace():
        if '\x0c' in text:
            return -0.8
        if '\t' in text and '\n' in text:
            return -0.17
        if '\r' in text and '\n' not in text:
            return -0.18
        if text.count('\n') >= 2 and ' ' in text and len(text) > 3:
            return -0.4
        if text.startswith(' ') and text.endswith('\n'):
            return 0.05 if len(text) <= 3 else -0.08
    if text == ' ;':
        return -0.42
    if text == ';' and previous in ('&gt', '&lt', '&amp', '&quot', '&nbsp'):
        return -0.5
    if stripped in ('^^', '~~', '_^'):
        return -0.45
    if stripped and set(stripped) == {'\\'} and len(stripped) >= 2:
        return -0.12 if len(stripped) == 2 else -0.65
    if stripped and set(stripped) == {'!'} and len(stripped) > 1:
        return -0.25
    # Incomplete letters following a space, distinguished by UTF-8 lead byte.
    if raw.startswith(b' ') and '\ufffd' in text:
        lead = raw[1] if len(raw) > 1 else 0
        if 0xC2 <= lead <= 0xC5:  # Latin letters and adjacent symbols
            return -0.63
        if lead == 0xD7:  # Hebrew
            return -1.5
        if lead not in (0xCE, 0xCF):  # Greek is common in mathematics
            return -0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, 0, 0, False, False, False)
    _, parens, brackets, comma_seen, tab_seen, display_math = carry
    text, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    previous = '' if first else prefix.token_strings[-2]
    prediction = typography(text, raw, previous)

    if text == ' ,':
        prediction = -0.1 if comma_seen else -0.4
        comma_seen = True
    elif text in (' )', ' ]'):
        balance = parens if text == ' )' else brackets
        prediction = -0.12 if balance > 0 else -0.65
    elif text == '\t\n':
        prediction = -0.05 if previous.endswith('\n') else (
            -0.32 if tab_seen else -0.47)
        tab_seen = True
    elif text.strip() == '$$':
        prediction = -0.33 if text.startswith(' ') else (
            -0.03 if display_math else -0.17)
    elif text == ' by':
        # Read only a short local suffix, within this document.
        start = max(0, len(prefix.token_strings) - 9)
        before = ''.join(prefix.token_strings[i] for i in range(start,
                         len(prefix.token_strings) - 1)
                         if prefix.document_ids[i] == doc)
        match = re.search(r'([A-Za-z]+)$', before)
        if match and match[1].lower() in CREDIT_VERBS:
            word = match[1]
            header = before[:match.start()].rstrip(' #*/')
            prediction = 1.5 if not header or header.endswith('\n') else (
                0.65 if word[0].isupper() else 0.15)

    if prediction == 0.0 and not text.isspace():
        if first or previous == '<|endoftext|>':
            prediction = 0.21
    parens = max(0, parens + text.count('(') - text.count(')'))
    brackets = max(0, brackets + text.count('[') - text.count(']'))
    display_math ^= bool(text.count('$$') % 2)
    return (doc, parens, brackets, comma_seen, tab_seen, display_math), prediction

programs.haiku:
"""Draft 1: a strong negative spike on the end-of-turn token <|im_end|>, which closes
a chat message, except when it follows a tool-call tag, where the spike is weak."""

READS = ()

END_OF_TURN = "<|im_end|>"
WEAK_AFTER = {"</tool_response>": -0.6, "</tool_call>": -0.2}
SPIKE = -1.9


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if tokens[-1] != END_OF_TURN:
        return carry, 0.0
    if len(tokens) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, SPIKE
    return carry, WEAK_AFTER.get(tokens[-2], SPIKE)

programs.sol:
"""Approximate a CJK word-stitching signal at token boundaries.

A token can have a familiar meaning of its own while its first character
actually completes a word begun to its left (政 | 治理, for example).
Look for such competing words in Chinese/Japanese frequency tables.  A
word already ending on the left weakens this evidence.  Numbers followed
by merged unit/continuation tokens are a related boundary case.

Only a short byte suffix is carried, so split UTF-8 characters are restored.
Document beginnings get a separate coarse character-shape estimate.  This
ignores the component's many small, token-specific fluctuations.
"""
from functools import lru_cache
from math import log10
import regex
import jmdict
from wordfreq import get_frequency_dict
from opencc import OpenCC

READS = ()
_CHINESE = get_frequency_dict('zh')
_JAPANESE = get_frequency_dict('ja')
_SIMPLIFY = OpenCC('t2s')
UNITS = frozenset('年月日时時分秒万元億亿千百十余餘多%岁歳歲')


@lru_cache(maxsize=100000)
def frequency(word, japanese=False):
    """Zipf word frequency; zero means absent from the frequency table."""
    if japanese:
        f = _JAPANESE.get(word, 1e-9)
    else:
        f = _CHINESE.get(_SIMPLIFY.convert(word), 1e-9)
    return max(0.0, 9.0 + log10(f))


def either_frequency(word):
    return max(frequency(word), frequency(word, True))


@lru_cache(maxsize=50000)
def boundary_words(history, token):
    """Frequencies of crossing words, and words ending before the token."""
    old = max([0.0] + [either_frequency(history[-n:])
                       for n in range(2, min(4, len(history)) + 1)])
    inside = whole = 0.0
    for n in range(1, min(3, len(history)) + 1):
        left = history[-n:]
        if not regex.fullmatch(r'[\p{Han}\p{Hiragana}\p{Katakana}]+', left):
            continue
        for end in range(1, min(5, len(token)) + 1):
            f = either_frequency(left + token[:end])
            if end < len(token):
                inside = max(inside, f)
            else:
                whole = max(whole, f)
    return inside, whole, old


def beginning(token):
    length = len(token.strip())
    if length == 0:
        return 0.23 if token.startswith(' ') else 0.56
    if length == 1:
        return 0.16 if token.isdigit() else -0.04
    if length > 11:
        return 0.07
    if not token.isascii():
        return -0.10
    return -0.32 if token.isalpha() else -0.21


def estimate(token, previous, history):
    if not regex.search(r'\p{Han}', token):
        return -0.003
    if len(token) < 2:
        return -0.01
    suffix = frequency(token[1:])
    current = frequency(token)
    inside, whole, old = boundary_words(history, token)
    if history and history[-1].isdigit():
        if suffix > 4.25:
            return 0.65 if token[0] in UNITS else 0.17
        return -0.01
    if old > 0 and old > inside - 0.75 and current > 4.8:
        return -0.01
    if inside > 3.5 and len(previous) <= 1:
        if jmdict.glosses(token):
            return 1.07
        return 0.56 if current > 2.88 else 0.21
    if inside > 0 and len(previous) <= 1 and current < 4.85:
        return 0.14
    if whole > 2 and old < 1:
        return 0.28
    if inside > 3.15 and len(previous) == 2 and frequency(previous) < 3.85:
        return 0.15
    return -0.01


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        raw, previous = b'', ''
    else:
        _, raw, previous = carry
    if previous == '<|endoftext|>':
        raw, previous = b'', ''
    token = prefix.token_strings[-1]
    history = raw.decode('utf-8', 'ignore')[-8:]
