"""Draft 4: a handful of concept rules, each with a fitted size.

Most tokens: 0. The component is a sparse, lexically spread feature, so the rules
capture only its main sources:

1. First token of a row (no context before it): whitespace and digits push it up, a
   word (with or without a leading space) pushes it down, other tokens slightly down.
2. A run of middle dots '··' (table-of-contents leaders): a steady positive value.
3. Chinese words (2+ characters) that involve quantities or times:
   - containing a number/quantity character (万 亿 千 百 十 元): positive;
   - containing a time character (年 月 日 季 底 初 午): positive;
   - ending in a place/measure character (年 段 院 料 上): positive;
   - directly after a digit: strongly positive; after a number or modifier word
     (一 每 大 小 第 这 ...): weakly positive.
"""

READS = ()

QTY = set("万亿千百十元")
TIME = set("年月日季底初午")
UNIT_END = set("年段院料上")
NUMBER_START = set("一二三四五六七八九十百千万亿多几两")
DIGITS = set("0123456789")
MODIFIERS = set("一二三四五六七八九十百千万亿多几两每大小第这某")


def is_chinese_word(s):
    return len(s) >= 2 and all("一" <= ch <= "鿿" for ch in s)


def is_ascii_word(s):
    s = s.strip(" ")
    return s.isascii() and s.isalpha()


def row_start_value(s):
    if s.strip() == "":
        return 0.37
    if s[0].isdigit():
        return 0.17
    if is_ascii_word(s):
        return -0.24
    return -0.07


