    s = prefix.token_strings[-1]
    if prefix.position == 0:
        return None, row_start_value(s)
    if s == "··":
        return None, 0.52
    if not is_chinese_word(s):
        return None, 0.0
    prev = prefix.token_strings[-2]
    value = 0.0
    if any(ch in QTY for ch in s):
        value += 0.2
    if any(ch in TIME for ch in s):
        value += 0.12
    if s[-1] in UNIT_END:
        value += 0.18
    if s[0] in NUMBER_START:
        value += 0.05
    if any(ch in DIGITS for ch in prev):
        value += 0.4
    elif any(ch in MODIFIERS for ch in prev):
        value += 0.08
    return None, value

