        host = host.group() if host else ''
        value = {'.com': 0.9, '.org': 0.65, '.net': 0.25,
                 '.uk': 0.8, '.edu': 0.4}[s]
        if s == '.org' and host.endswith('wikipedia'):
            value = 8.1 if '://' in tail else 5.5
        elif s == '.com':
            if host.endswith('google'):
                value = 5.6 if '://' in tail else 2.9
            elif host.endswith(('stackexchange', 'stackoverflow')):
                value = 5.5
            elif host.endswith(('twitter', 'reddit', 'facebook')):
                subdomain = (host.endswith('twitter')
                             and previous.startswith('.'))
                value = 1.5 if subdomain else 4.2
            elif host == 'amazon':
                value = 5.2
            elif host.endswith('github'):
                value = 0.4
    elif s == '/wiki' and tail.lower().endswith('wikipedia.org'):
        value = 4.4
    elif s in {'.wikipedia', '.amazon'}:
        value = 2.2

    return (doc, t, (tail + t)[-100:], pats, raw), float(value)

programs.haiku:
"""Candidate 7: a readable model of where one down-projection feature fires.

Mostly negative on the Chinese character 拍 (pai: shoot/photograph/auction) and on Python
or test dunder names (__name__, __call__, __tests__); positive on the domain ending
(.com, .org) of big websites (google.com, amazon.com, en.wikipedia.org) and on /wiki.
Everything else predicts 0. Stateless: each token is judged from itself and the one before.
"""
READS = ()

TOP_SITES = {"amazon", "wikipedia", "google", "youtube", "twitter", "reddit", "stackoverflow"}
OTHER_SITES = {"facebook", "yahoo", "baidu", "microsoft", "instagram", "blogspot", "wordpress",
               "imgur", "unsplash", "apple", "linkedin"}
DOMAIN_ENDINGS = {".com", ".org", ".net", ".edu", ".gov", ".io", ".co", ".uk"}
GENERIC_ENDINGS = {".com", ".org", ".uk"}
DUNDER_NAMES = {"name", "call", "all", "doc", "file", "files", "future", "import", "class",
                "new", "eq", "hash", "getattr", "data", "param", "get", "test", "tests"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    site = previous.strip(" ./@").lower()
    after_underscores = previous.rstrip().endswith("__")
    if token in ("拍", "拍拍", "拍卖"):
        value = -7.0
    elif "拍" in token:
        value = -2.0
    elif token in ("拿", "卖"):
        value = -1.2
    elif token == "/wiki":
        value = 4.0
    elif token in DOMAIN_ENDINGS and site in TOP_SITES:
        value = 6.0
    elif token in DOMAIN_ENDINGS and site in OTHER_SITES:
        value = 2.0
    elif token in GENERIC_ENDINGS:
        value = 0.5
    elif after_underscores and token.strip() in DUNDER_NAMES:
        value = -3.5
    elif after_underscores and token.strip() == "construct":
        value = 3.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A short-fragment 'ke' detector, not a whole-word keyword detector.

Short ke fragments give negative outputs, especially at word starts and before
m/s/b/v/f/w/h. The k and e may lie in different tokens or alphabets; kh and q
also qualify as preceding k-like consonants. Corpus word frequencies damp
common English, German and Dutch word endings.
The response can continue onto the next unspaced letter fragment. Additional,
separate rules cover mechanical kilo-units, Arabic kaf continuations and dot runs.
This approximates the spelling pattern, not its full context-dependent strength.
"""
import codecs
import re
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
STRONG_FOLLOWERS = frozenset('msbvfwh')
MECHANICAL_UNITS = frozenset(('J', 'W', 'N'))  # joule, watt, newton


@lru_cache(maxsize=50000)
def spelling(text):
    # Do not turn Chinese words into romanized letter fragments.
    if regex.search(r'\p{Script=Han}', text):
        return ''
    # Thai writes this vowel before its consonant.
    return anyascii(text.replace('เก', 'ke').replace('เค', 'ke')).lower()


@lru_cache(maxsize=50000)
def rarity(word, name=False):
    if len(word) < 3:
        return 1.0
    frequency = max(zipf_frequency(word, language)
                    for language in ('en', 'de', 'nl'))
    if name and frequency < 4.0:
        return 1.0
    return max(0.0, min(1.0, (4.7 - frequency) / 2.7))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', '', '', False)
    _, pending, previous, word, previous_text, name = carry
    split_character = bool(pending)
    decoder = codecs.getincrementaldecoder('utf8')('ignore')
    decoder.setstate((pending, 0))
    text = decoder.decode(prefix.token_bytes[-1])
    pending = decoder.getstate()[0]
    if not text:
        return (doc, pending, previous, word, previous_text, name), 0.0

    s = spelling(text)
    space = text[:1].isspace()
    if s and not s[0].isalpha():
        word = ''
    partial_word = bool(word)
    if not word:
        name = next((c for c in text if c.isalpha()), '').isupper()
    match = re.search('[a-z]+$', word + s)
    newword = match[0][-40:] if match else ''
    value = 0.0

    fragment = s.lstrip(' ._-/')
    k = fragment.find('ke')
    if 0 <= k <= 2 and len(fragment) <= 6:
        r = (1.0 if newword == fragment and k == 0
             and len(fragment) <= 3 and fragment[-1:] != 'y'
             else rarity(newword, name and partial_word))
        if r > 0.0:
            after_e = fragment[k+2:k+3]
            if len(fragment) > 3:
                value -= 0.08
            elif after_e in STRONG_FOLLOWERS:
                value -= 4.4 if space else 2.75
            elif fragment == 'ke':
                value -= 2.1 if space else 1.25
            elif space:
                value -= 1.45
            else:
                value -= 0.55 if r > 0.67 else 0.12
            if split_character:
                value -= 1.5

    joined = bool(s and not space and s[0].isalpha())
    if joined and previous.endswith(('k', 'kh', 'q')):
        if s.startswith('e') and rarity(newword, name) > 0.0:
            after_e = s[1:2]
            if previous.strip() in ('k', 'kh', 'q'):
                if 2 <= len(s) <= 3:
                    if after_e in ('n', 'r'):
                        value -= 1.12
                    else:
                        value -= 3.74 if after_e in STRONG_FOLLOWERS else 2.53
                else:
                    value -= 1.25
            elif rarity(newword, name) < 0.99:
                value -= 0.25
            elif len(s) <= 4:
                value -= 2.6 if after_e in STRONG_FOLLOWERS else 1.03
        elif s[0] not in 'aeiouy':
            if previous.strip() == 'k' and text in MECHANICAL_UNITS:
                value += 3.2
            if previous_text.strip() in ('ك', 'ک'):
                value += 0.4 + (3.9 if text == 'ه' else 0.0)

    if joined and word.endswith('ke'):
        if s[0] in 'aeiouy':
            value -= 0.36
        elif len(s) > 1:
            value -= 0.33
        elif rarity(newword) < 0.78:
            value -= 2.3
        else:
            value -= 3.7 if s[0] in 'bdgjvz' else 2.6

    if text.strip() in ('kJ', 'kW', 'kN'):
        value += 1.7
    if len(text) > 1 and set(text) == {'·'}:
        value -= 1.3
    return (doc, pending, s, newword, text, name), float(value)

programs.haiku:
"""Draft 5: demonstrative determiners ('this', 'these', 'ce', 'este', 'diesem', ...) and
lone spaces that follow indentation."""

READS = ()

ENGLISH = {"this", "these"}
ROMANCE_GERMAN = {
    "ce", "cet", "cette", "ces", "ceci", "cela", "este", "esta", "estos", "estas", "esto",
    "questo", "questa", "questi", "queste", "quest", "esse", "essa", "esses", "essas",
    "isto", "isso", "dies", "dieses", "diese", "diesem", "diesen", "dieser",
}
RUSSIAN = {"эта", "этот", "эти", "этой", "эту", "этом", "этих", "этого", "это"}
CJK_KOREAN = {"この", "その", "これ", "这个", "这些", "这种", "이"}
CODE_BEFORE = {"=", "(", ")", ".", "return", "||", "&&", "!", ""}  # code, not prose


def _trailing_letters(s):
    word = ""
    for ch in reversed(s):
        if not ch.isalpha():
            break
        word = ch + word
    return word


def step(carry, prefix, upstream):
    # carry: (letters of the current word so far, previous token string)
    word, prev = carry if carry is not None else ("", None)
    doc = prefix.document_ids
    if len(doc) > 1 and doc[-1] != doc[-2]:
        word, prev = "", None
    s = prefix.token_strings[-1]
    if s.isalpha():
        word = word + s
    else:
        word = _trailing_letters(s)
    low = word.lower()
    before = "" if prev is None else prev.strip()
    value = 0.0
    if low in ENGLISH:
        if word == low:  # lowercase: 'this' in prose, or the code keyword after '=' or '('
            value = -0.5 if ("(" in s or before in CODE_BEFORE) else 0.8
        else:  # capitalised, or without a leading space
            value = 0.6 if s[:1] == " " else 0.3
    elif low in ROMANCE_GERMAN:
        value = 1.5
    elif low in RUSSIAN:
        value = 1.0
    elif low in CJK_KOREAN:
        value = 0.4
    elif s == " " and prev is not None and prev != "" and set(prev) <= {" ", "\t"}:
        value = 1.1  # a lone space right after indentation, before a number
    elif len(s) >= 2 and set(s) == {"·"}:
        value = -1.45  # a run of middle dots
    return (word, s), value

programs.sol:
"""An initial-token-run pulse, modulated by the token's readable kind.

The component is nearly silent after a document acquires varied tokens.
On its initial run of identical tokens it is positive on most word pieces,
especially source-file namespace declarations, and weaker on function words,
spacing and punctuation. These are category
averages, not a vocabulary lookup; individual first tokens can differ greatly.
"""
import unicodedata
from functools import lru_cache

READS = ()
PREPOSITIONS = frozenset('''of to in for on with by from into onto upon under
    over between through before after during without within about against
    among across per via than as'''.split())
AUXILIARIES = frozenset('''be is am are was were been being have has had do does
    did can could would should will shall may might must'''.split())
CONJUNCTIONS = frozenset('''and or but nor so yet if because although since
    while unless until whether that'''.split())
PRONOUNS = frozenset('''i you he she it we they me him her us them my your his
    our their mine yours its ours theirs myself yourself himself herself
    itself ourselves themselves'''.split())
DETERMINERS = frozenset('''a an the this these those some any every each no
    all both either neither other such what which whose'''.split())


@lru_cache(maxsize=16000)
def first_token(s):
    t = s.strip()
    if t == '<|im_start|>':
        return 5.43
    if not t:
        if '\t\t' in s:
            return -7.0
        return 2.35 if len(s) > 1 and '\n' not in s else -0.9
    if t.isdigit():
        return 2.1
    # Source-file openings: namespace imports and package declarations.
    if s == 'using':
        return 19.1
    if s == 'package':
        return 13.7
    if not any(c.isalnum() for c in t):
        category = unicodedata.category(t[0])
        if category == 'Sc':
            return 3.7
        if category in ('Pe', 'Sm'):
            return 2.2
        if category in ('So', 'Pc'):
            return 3.4
        if category in ('Po', 'Ps') and len(t) > 1:
            return min(6.0, 1.2 * (len(t) - 1))
        return -0.7
    if t.isalpha():
        space = s[0].isspace()
        word = t.lower()
        if word in PRONOUNS:
            return 0.7
        if word in PREPOSITIONS or word in AUXILIARIES:
            return 0.4 if space else 2.6
        if word in CONJUNCTIONS:
            return 1.1 if space else 3.4
        if word in DETERMINERS:
            return 2.5 if space else 3.8
        name = unicodedata.name(t[0], '')
        if name.startswith(('ARABIC', 'GREEK')):
            return 5.6
        if name.startswith(('HIRAGANA', 'KATAKANA', 'HANGUL', 'THAI')):
            return 0.5
        if name.startswith('CJK'):
            return 2.1
        if name.startswith('LATIN'):
            if len(t) == 1:
                return 4.0 if space else 5.0
            if space:
                return max(1.8, 3.3 - 0.18 * len(t))
            return 4.3 if t[0].isupper() and len(t) <= 3 else 2.7
        return 2.5 if space else 3.5
    return 2.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first, initial_run = token, True
    else:
        _, first, initial_run = carry
        initial_run = initial_run and token == first
    value = first_token(prefix.token_strings[-1]) if initial_run else 0.0013
    return (doc, first, initial_run), value

programs.haiku:
"""Document-start word-class program for layers.1.mlp.down_proj:1599.

This component is active only at the first token of a document (its activation there depends
only on that token's identity). The program predicts that value from a coarse reading of the
token: special markers and code keywords give the largest values, capitalised and lowercase
word starts a medium value, function words and digits a small one, opening brackets, quotes,
commas and newlines slightly negative, and other punctuation slightly positive. Every other
position is 0. Per-token values are not hand-tuned; they are rounded class means measured on
training text.
"""

READS = ()

CODE_WORDS = frozenset(
    "package import using include #include int return def class public void var let const fn struct".split()
)
FUNCTION_WORDS = frozenset(
    "of to and is in with by are was not my you i he we she it at on for as the a an or that this be from".split()
)
OPENING = frozenset("([{\"'-#,.“")


def word_value(token):
    """Activation at a document's first token, from the token's kind."""
    if token.startswith("<|"):
        return 5.0
    text = token.strip()
    if not text:
        return -0.4
    if text.lower() in CODE_WORDS:
        return 7.0
    if not any(c.isalnum() for c in text):
        if "\n" in token:
            return -0.4
        return -1.0 if text[0] in OPENING else 0.5
    if text[0].isdigit():
        return 2.0
    if token.startswith(" "):
        return 1.0 if text.lower() in FUNCTION_WORDS else 2.3
    return 3.5 if text[0].isupper() else 3.0


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    starts_document = len(docs) == 1 or docs[-1] != docs[-2]
    if not starts_document:
        return None, 0.0
    return None, word_value(prefix.token_strings[-1])
